INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_daily_content_factory','daily-content-factory','Nhà Máy Nội Dung Hàng Ngày','Daily Content Factory','Tự động tạo 3 video AI và gửi email digest hàng ngày cho khách hàng','Auto-generate 3 AI avatar videos and send a daily email digest to customers','content',replace('agents:\n  content_planner:\n    role: Content Planner\n    goal: Plan 3 daily content topics\n    tools:\n      - analytics:report\n  video_creator:\n    role: Video Creator\n    goal: Create AI avatar videos\n    tools:\n      - video:create\n  email_publisher:\n    role: Email Publisher\n    goal: Send daily digest\n    tools:\n      - email:campaign','\n',char(10)),replace('# Daily Content Factory Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: topics\nlimit: 3\n```\n\n## Step 2: video:create\n```yaml\ntopic: "{{step_1.output.topics[0]}}"\n```\n\n## Step 3: video:create\n```yaml\ntopic: "{{step_1.output.topics[1]}}"\n```\n\n## Step 4: video:create\n```yaml\ntopic: "{{step_1.output.topics[2]}}"\n```\n\n## Step 5: email:campaign\n```yaml\nsubject: "Your Daily Video Digest"\ntemplate: daily_digest\n```','\n',char(10)),'{"type":"object","required":["videos","emailId"],"properties":{"videos":{"type":"array","items":{"type":"object"},"minItems":3},"emailId":{"type":"string"}}}',NULL,NULL,5,0,10,1,1,NULL,'published',1777783304,1777783304);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_reactive_lead_engine','reactive-lead-engine','Động Cơ Lead Phản Ứng','Reactive Lead Engine','Nhận webhook, làm giàu dữ liệu lead và gửi email cá nhân hóa tự động','Receive webhook, enrich lead data, and send a personalized email automatically','leads',replace('agents:\n  lead_enricher:\n    role: Lead Enricher\n    goal: Enrich lead data\n    tools:\n      - lead:enrich\n  email_writer:\n    role: Email Writer\n    goal: Send personalized email\n    tools:\n      - email:test','\n',char(10)),replace('# Reactive Lead Engine Playbook\n\n## Step 1: lead:enrich\n```yaml\nemail: "{{trigger.body.email}}"\n```\n\n## Step 2: email:test\n```yaml\nto: "{{step_1.output.email}}"\nsubject: "Quick question"\n```','\n',char(10)),'{"type":"object","required":["leadId","enriched","emailId"],"properties":{"leadId":{"type":"string"},"enriched":{"type":"object"},"emailId":{"type":"string"}}}',NULL,NULL,5,0,2,1,1,NULL,'published',1777783304,1777783304);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_weekly_performance_report','weekly-performance-report','Báo Cáo Hiệu Suất Hàng Tuần','Weekly Performance Report','Tự động truy vấn analytics, tạo báo cáo và gửi email hàng tuần','Auto-query analytics, generate performance report, and email weekly summary','analytics',replace('agents:\n  analytics_reporter:\n    role: Analytics Reporter\n    goal: Generate weekly metrics\n    tools:\n      - analytics:report\n  report_sender:\n    role: Report Sender\n    goal: Email the report\n    tools:\n      - email:campaign','\n',char(10)),replace('# Weekly Performance Report Playbook\n\n## Step 1: analytics:report\n```yaml\nperiod: last_7_days\n```\n\n## Step 2: email:campaign\n```yaml\nsubject: "Weekly Performance Report"\ntemplate: weekly_report\n```','\n',char(10)),'{"type":"object","required":["reportId","emailId","metricsSnapshot"],"properties":{"reportId":{"type":"string"},"emailId":{"type":"string"},"metricsSnapshot":{"type":"object"}}}',NULL,NULL,5,0,1,1,1,NULL,'published',1777783304,1777783304);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_proposal_auto_pilot','proposal-auto-pilot','Tự Động Gửi Đề Xuất','Proposal Auto-Pilot','Hàng ngày tìm 5 lead, tạo đề xuất cá nhân hóa và gửi cho từng người','Daily: find 5 prospects, create personalized proposals, and send to each one','proposals',replace('agents:\n  lead_finder:\n    role: Lead Finder\n    goal: Find 5 prospects\n    tools:\n      - lead:find\n  proposal_creator:\n    role: Proposal Creator\n    goal: Create proposals\n    tools:\n      - proposal:create\n  proposal_sender:\n    role: Proposal Sender\n    goal: Send proposals\n    tools:\n      - email:campaign','\n',char(10)),replace('# Proposal Auto-Pilot Playbook\n\n## Step 1: lead:find\n```yaml\nlimit: 5\n```\n\n## Step 2: proposal:create\n```yaml\nleads: "{{step_1.output.leads}}"\n```\n\n## Step 3: email:campaign\n```yaml\nproposals: "{{step_2.output.proposals}}"\n```','\n',char(10)),'{"type":"object","required":["proposals"],"properties":{"proposals":{"type":"array","items":{"type":"object","properties":{"proposalId":{"type":"string"},"leadId":{"type":"string"}},"required":["proposalId","leadId"]},"minItems":1}}}',NULL,NULL,5,0,5,1,1,NULL,'published',1777783304,1777783304);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_crisis_pr_mode','crisis-pr-mode','Chế Độ Khủng Hoảng PR','Crisis PR Mode','Theo dõi đề cập thương hiệu, soạn thảo phản hồi — yêu cầu phê duyệt người trước khi gửi','Monitor brand mentions, draft crisis response — requires human approval before sending','crisis',replace('agents:\n  mention_monitor:\n    role: Mention Monitor\n    goal: Detect negative mentions\n    tools:\n      - analytics:report\n  response_drafter:\n    role: Response Drafter\n    goal: Draft crisis response\n    tools:\n      - proposal:create','\n',char(10)),replace('# Crisis PR Mode Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: mentions\nsentiment: negative\n```\n\n## Step 2: proposal:create\n```yaml\ntype: crisis_response\nrequires_approval: true\n```','\n',char(10)),'{"type":"object","required":["mentionsReport","draftResponseId","requiresApproval"],"properties":{"mentionsReport":{"type":"object"},"draftResponseId":{"type":"string"},"requiresApproval":{"type":"boolean","const":true}}}',NULL,NULL,5,0,3,1,1,NULL,'published',1777783304,1777783304);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_daily_tiktok_3x','daily-tiktok-3x','TikTok 3 Video / Ngày','Daily TikTok 3x','Tự động đăng 3 video TikTok mỗi ngày với hook template theo ngách của bạn','Auto-post 3 TikTok videos daily with niche-specific hook templates','content',replace('agents:\n  hook_writer:\n    role: Hook Writer\n    goal: Write 3 attention-grabbing TikTok hooks for {{config.niche}}\n    tools:\n      - ai:write\n    backstory: Viral TikTok copywriter specializing in first-3-second hooks\n\n  video_creator:\n    role: Video Creator\n    goal: Create short-form video for each hook\n    tools:\n      - video:create\n    backstory: Short-form video specialist using AI avatars\n\n  tiktok_publisher:\n    role: TikTok Publisher\n    goal: Schedule and publish videos to TikTok\n    tools:\n      - social:publish\n    backstory: Social media automation expert','\n',char(10)),replace('# Daily TikTok 3x Playbook\n\n## Step 1: ai:write\n```yaml\ntask: generate_hooks\nniche: "{{config.niche}}"\ncount: {{config.daily_count}}\ntone: "{{config.tone}}"\nformat: tiktok_hook\n```\n\n## Step 2: video:create\n```yaml\nscript: "{{step_1.output.hooks[0]}}"\navatar_id: default\nduration: 30\nformat: vertical_9x16\n```\n\n## Step 3: video:create\n```yaml\nscript: "{{step_1.output.hooks[1]}}"\navatar_id: default\nduration: 30\nformat: vertical_9x16\n```\n\n## Step 4: video:create\n```yaml\nscript: "{{step_1.output.hooks[2]}}"\navatar_id: default\nduration: 30\nformat: vertical_9x16\n```\n\n## Step 5: social:publish\n```yaml\nplatform: tiktok\nvideo_ids:\n  - "{{step_2.output.videoId}}"\n  - "{{step_3.output.videoId}}"\n  - "{{step_4.output.videoId}}"\ncaption_template: "{{config.caption_suffix}}"\nschedule: spread_evenly\n```','\n',char(10)),'{"type":"object","required":["videoIds","publishedCount"],"properties":{"videoIds":{"type":"array","items":{"type":"string"},"minItems":1},"publishedCount":{"type":"integer"}}}','{"properties":{"niche":{"type":"string","title":"Niche / Industry","description":"Your content niche (e.g. fitness, finance, SaaS)","placeholder":"e.g. Digital marketing for restaurants"},"daily_count":{"type":"integer","title":"Videos per day","default":3,"minimum":1,"maximum":5},"tone":{"type":"string","title":"Content tone","enum":["professional","casual","witty","educational"],"default":"casual"},"caption_suffix":{"type":"string","title":"Caption suffix / hashtags","placeholder":"#growth #agency","default":""}},"required":["niche"]}','{"daily_count":3,"tone":"casual","caption_suffix":""}',5,1,6,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_weekly_youtube_longform','weekly-youtube-longform','YouTube Dài Hàng Tuần','Weekly YouTube Longform','Tự động tạo và đăng 1 video YouTube dài (10-15 phút) mỗi tuần','Auto-create and publish one 10-15 min YouTube video every week','content',replace('agents:\n  topic_researcher:\n    role: Topic Researcher\n    goal: Find trending topics in {{config.niche}} for YouTube\n    tools:\n      - analytics:report\n    backstory: YouTube SEO strategist tracking trending searches\n\n  script_writer:\n    role: Script Writer\n    goal: Write a full 10-minute video script\n    tools:\n      - ai:write\n    backstory: Expert YouTube script writer with hook-body-CTA structure\n\n  video_producer:\n    role: Video Producer\n    goal: Produce and render long-form video\n    tools:\n      - video:create\n    backstory: Video production specialist for long-form content','\n',char(10)),replace('# Weekly YouTube Longform Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: trending_topics\nniche: "{{config.niche}}"\nplatform: youtube\nlimit: 5\n```\n\n## Step 2: ai:write\n```yaml\ntask: youtube_script\ntopic: "{{step_1.output.topics[0]}}"\nduration_minutes: {{config.video_duration}}\ntarget_audience: "{{config.target_audience}}"\nstyle: educational_entertaining\ninclude_cta: true\n```\n\n## Step 3: video:create\n```yaml\nscript: "{{step_2.output.script}}"\navatar_id: default\nduration: {{config.video_duration}}\nformat: landscape_16x9\nthumbnail_auto: true\n```\n\n## Step 4: social:publish\n```yaml\nplatform: youtube\nvideo_id: "{{step_3.output.videoId}}"\ntitle: "{{step_2.output.title}}"\ndescription: "{{step_2.output.description}}"\ntags: "{{step_1.output.tags}}"\nvisibility: public\n```','\n',char(10)),'{"type":"object","required":["videoId","youtubeUrl"],"properties":{"videoId":{"type":"string"},"youtubeUrl":{"type":"string"}}}','{"properties":{"niche":{"type":"string","title":"Niche / Topic","placeholder":"e.g. Personal finance for millennials"},"target_audience":{"type":"string","title":"Target audience","placeholder":"e.g. Small business owners aged 25-45"},"video_duration":{"type":"integer","title":"Video duration (minutes)","default":12,"minimum":8,"maximum":20}},"required":["niche"]}','{"video_duration":12}',8,0,15,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_daily_instagram_reels','daily-instagram-reels','Instagram Reels 3 Video / Ngày','Daily Instagram Reels 3x','Đăng 3 Instagram Reels mỗi ngày với âm thanh trending và caption phù hợp','Post 3 Instagram Reels daily with trending audio and optimized captions','content',replace('agents:\n  content_planner:\n    role: Content Planner\n    goal: Plan 3 Reels topics for {{config.brand_name}} in {{config.niche}}\n    tools:\n      - ai:write\n    backstory: Instagram growth strategist\n\n  video_creator:\n    role: Video Creator\n    goal: Create vertical Reels videos\n    tools:\n      - video:create\n    backstory: Short-form video expert\n\n  ig_publisher:\n    role: Instagram Publisher\n    goal: Publish Reels to Instagram account\n    tools:\n      - social:publish\n    backstory: Social media automation specialist','\n',char(10)),replace('# Daily Instagram Reels Playbook\n\n## Step 1: ai:write\n```yaml\ntask: reels_content_plan\nbrand: "{{config.brand_name}}"\nniche: "{{config.niche}}"\ncount: 3\ntone: "{{config.tone}}"\ninclude_hashtags: true\n```\n\n## Step 2: video:create\n```yaml\nscript: "{{step_1.output.scripts[0]}}"\nformat: vertical_9x16\nduration: 30\n```\n\n## Step 3: video:create\n```yaml\nscript: "{{step_1.output.scripts[1]}}"\nformat: vertical_9x16\nduration: 30\n```\n\n## Step 4: video:create\n```yaml\nscript: "{{step_1.output.scripts[2]}}"\nformat: vertical_9x16\nduration: 30\n```\n\n## Step 5: social:publish\n```yaml\nplatform: instagram\ntype: reels\nvideo_ids:\n  - "{{step_2.output.videoId}}"\n  - "{{step_3.output.videoId}}"\n  - "{{step_4.output.videoId}}"\ncaptions: "{{step_1.output.captions}}"\nhashtags: "{{step_1.output.hashtags}}"\nschedule: spread_evenly\n```','\n',char(10)),'{"type":"object","required":["publishedCount"],"properties":{"publishedCount":{"type":"integer"},"postUrls":{"type":"array","items":{"type":"string"}}}}','{"properties":{"brand_name":{"type":"string","title":"Brand / Account Name","placeholder":"e.g. Sophia Agency"},"niche":{"type":"string","title":"Niche","placeholder":"e.g. business coaching, beauty, food"},"tone":{"type":"string","title":"Content tone","enum":["professional","casual","inspirational","humorous"],"default":"casual"}},"required":["brand_name","niche"]}','{"tone":"casual"}',5,0,6,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_multi_channel_crosspost','multi-channel-crosspost','Đăng Chéo Đa Kênh','Multi-Channel Crosspost','1 video → tự động đăng lên TikTok, Instagram Reels, YouTube Shorts và Twitter/X','1 video → auto-repurpose and post to TikTok, IG Reels, YouTube Shorts, Twitter/X','content',replace('agents:\n  content_adapter:\n    role: Content Adapter\n    goal: Adapt captions and hashtags for each platform\n    tools:\n      - ai:write\n    backstory: Multi-platform content strategist\n\n  crosspost_publisher:\n    role: Crosspost Publisher\n    goal: Publish adapted content to all selected platforms\n    tools:\n      - social:publish\n    backstory: Social media distribution specialist','\n',char(10)),replace('# Multi-Channel Crosspost Playbook\n\n## Step 1: ai:write\n```yaml\ntask: adapt_captions\noriginal_caption: "{{config.original_caption}}"\nplatforms:\n  - tiktok\n  - instagram\n  - youtube\n  - twitter\nbrand_voice: "{{config.tone}}"\ninclude_hashtags: true\n```\n\n## Step 2: social:publish\n```yaml\nplatform: tiktok\nvideo_url: "{{config.video_url}}"\ncaption: "{{step_1.output.captions.tiktok}}"\nhashtags: "{{step_1.output.hashtags.tiktok}}"\n```\n\n## Step 3: social:publish\n```yaml\nplatform: instagram\ntype: reels\nvideo_url: "{{config.video_url}}"\ncaption: "{{step_1.output.captions.instagram}}"\nhashtags: "{{step_1.output.hashtags.instagram}}"\n```\n\n## Step 4: social:publish\n```yaml\nplatform: youtube\ntype: shorts\nvideo_url: "{{config.video_url}}"\ntitle: "{{step_1.output.captions.youtube}}"\n```\n\n## Step 5: social:publish\n```yaml\nplatform: twitter\nvideo_url: "{{config.video_url}}"\ntweet: "{{step_1.output.captions.twitter}}"\n```','\n',char(10)),'{"type":"object","required":["publishedPlatforms"],"properties":{"publishedPlatforms":{"type":"array","items":{"type":"string"}}}}','{"properties":{"video_url":{"type":"string","title":"Source video URL","placeholder":"https://..."},"original_caption":{"type":"string","title":"Original caption / topic","placeholder":"Brief description of what the video is about"},"tone":{"type":"string","title":"Brand tone","enum":["professional","casual","witty","educational"],"default":"casual"}},"required":["video_url","original_caption"]}','{"tone":"casual"}',7,0,8,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_auto_subtitle_translate','auto-subtitle-translate','Tự Động Phụ Đề & Dịch Thuật','Auto Subtitle & Translate','Tự động tạo phụ đề và dịch video giữa tiếng Anh và tiếng Việt','Auto-generate subtitles and translate video between English and Vietnamese','content',replace('agents:\n  transcriber:\n    role: Transcriber\n    goal: Transcribe speech from video to text\n    tools:\n      - ai:transcribe\n    backstory: Speech-to-text specialist with high accuracy\n\n  translator:\n    role: Translator\n    goal: Translate transcript to target language\n    tools:\n      - ai:translate\n    backstory: Professional translator for EN-VI\n\n  subtitle_renderer:\n    role: Subtitle Renderer\n    goal: Burn subtitles into video and export\n    tools:\n      - video:subtitle\n    backstory: Video post-production specialist','\n',char(10)),replace('# Auto Subtitle & Translate Playbook\n\n## Step 1: ai:transcribe\n```yaml\nvideo_url: "{{config.video_url}}"\nsource_language: "{{config.source_language}}"\n```\n\n## Step 2: ai:translate\n```yaml\ntext: "{{step_1.output.transcript}}"\nsource_lang: "{{config.source_language}}"\ntarget_lang: "{{config.target_language}}"\n```\n\n## Step 3: video:subtitle\n```yaml\nvideo_url: "{{config.video_url}}"\nsubtitles:\n  original: "{{step_1.output.srt}}"\n  translated: "{{step_2.output.srt}}"\nstyle: "{{config.subtitle_style}}"\nburn_in: true\n```','\n',char(10)),'{"type":"object","required":["outputVideoUrl","transcript"],"properties":{"outputVideoUrl":{"type":"string"},"transcript":{"type":"string"},"translatedText":{"type":"string"}}}','{"properties":{"video_url":{"type":"string","title":"Video URL to process","placeholder":"https://..."},"source_language":{"type":"string","title":"Original language","enum":["en","vi"],"default":"en"},"target_language":{"type":"string","title":"Translation language","enum":["vi","en"],"default":"vi"},"subtitle_style":{"type":"string","title":"Subtitle style","enum":["standard","bold","highlight"],"default":"standard"}},"required":["video_url"]}','{"source_language":"en","target_language":"vi","subtitle_style":"standard"}',3,0,4,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_voice_clone_narration','voice-clone-narration','Nhân Bản Giọng Nói AI (BETA)','Voice Clone Narration (BETA)','Nhân bản giọng nói và tạo narration AI cho video sản phẩm — tính năng thử nghiệm','Clone your voice and generate AI narration for product videos — BETA feature','content',replace('agents:\n  script_writer:\n    role: Script Writer\n    goal: Write narration script for {{config.product_name}}\n    tools:\n      - ai:write\n    backstory: Product video copywriter\n\n  voice_narrator:\n    role: Voice Narrator\n    goal: Generate narration using cloned voice profile\n    tools:\n      - voice:clone_narrate\n    backstory: ElevenLabs voice synthesis specialist (BETA)\n\n  video_merger:\n    role: Video Merger\n    goal: Merge narration audio with product video\n    tools:\n      - video:merge_audio\n    backstory: Video post-production engineer','\n',char(10)),replace('# Voice Clone Narration Playbook (BETA)\n\n## Step 1: ai:write\n```yaml\ntask: product_narration_script\nproduct_name: "{{config.product_name}}"\nkey_benefits: "{{config.key_benefits}}"\nduration_seconds: {{config.duration_seconds}}\ntone: "{{config.tone}}"\n```\n\n## Step 2: voice:clone_narrate\n```yaml\ntext: "{{step_1.output.script}}"\nvoice_profile_id: "{{config.voice_profile_id}}"\nspeed: 1.0\n```\n\n## Step 3: video:merge_audio\n```yaml\nvideo_url: "{{config.video_url}}"\naudio_url: "{{step_2.output.audioUrl}}"\nreplace_original_audio: true\n```','\n',char(10)),'{"type":"object","required":["outputVideoUrl"],"properties":{"outputVideoUrl":{"type":"string"},"audioUrl":{"type":"string"},"script":{"type":"string"}}}','{"properties":{"product_name":{"type":"string","title":"Product name","placeholder":"e.g. Sophia AI Pro Plan"},"key_benefits":{"type":"string","title":"Key benefits (comma-separated)","placeholder":"e.g. saves 10 hours/week, automates social media"},"video_url":{"type":"string","title":"Source video URL","placeholder":"https://..."},"voice_profile_id":{"type":"string","title":"Voice profile ID (from ElevenLabs)","placeholder":"elevenlabs_voice_xxxxx"},"duration_seconds":{"type":"integer","title":"Target duration (seconds)","default":60,"minimum":15,"maximum":180},"tone":{"type":"string","title":"Narration tone","enum":["professional","conversational","enthusiastic"],"default":"professional"}},"required":["product_name","key_benefits"]}','{"duration_seconds":60,"tone":"professional"}',10,0,10,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_branded_intro_outro','branded-intro-outro','Gắn Intro/Outro Thương Hiệu','Branded Intro & Outro','Tự động thêm intro và outro thương hiệu vào mỗi video trước khi đăng','Auto-add branded intro and outro overlay to every video before publishing','content',replace('agents:\n  video_editor:\n    role: Video Editor\n    goal: Merge intro, main video, and outro into final cut\n    tools:\n      - video:edit\n    backstory: Professional video editor specializing in brand consistency\n\n  quality_checker:\n    role: Quality Checker\n    goal: Verify final video meets quality standards\n    tools:\n      - video:analyze\n    backstory: Video QA specialist','\n',char(10)),replace('# Branded Intro/Outro Playbook\n\n## Step 1: video:edit\n```yaml\noperation: merge_clips\nclips:\n  - url: "{{config.intro_url}}"\n    position: start\n  - url: "{{config.main_video_url}}"\n    position: middle\n  - url: "{{config.outro_url}}"\n    position: end\noutput_format: mp4\nadd_watermark: "{{config.watermark_text}}"\n```\n\n## Step 2: video:analyze\n```yaml\nvideo_url: "{{step_1.output.outputUrl}}"\nchecks:\n  - audio_levels\n  - resolution\n  - duration\n```','\n',char(10)),'{"type":"object","required":["outputVideoUrl","duration"],"properties":{"outputVideoUrl":{"type":"string"},"duration":{"type":"number"}}}','{"properties":{"main_video_url":{"type":"string","title":"Main video URL","placeholder":"https://..."},"intro_url":{"type":"string","title":"Branded intro video URL","placeholder":"https://... (5-10 second clip)"},"outro_url":{"type":"string","title":"Branded outro video URL","placeholder":"https://... (5-10 second clip)"},"watermark_text":{"type":"string","title":"Watermark text (optional)","placeholder":"e.g. @YourBrand","default":""}},"required":["main_video_url"]}','{"watermark_text":""}',7,0,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_evergreen_content_recycle','evergreen-content-recycle','Tái Chế Nội Dung Evergreen','Evergreen Content Recycle','Hàng tháng tự động tái đăng nội dung hoạt động tốt nhất với caption mới','Monthly auto-repost of top-performing content with fresh captions','content',replace('agents:\n  performance_analyzer:\n    role: Performance Analyzer\n    goal: Find top 3 performing posts from last 30 days\n    tools:\n      - analytics:report\n    backstory: Social media analytics expert\n\n  caption_refresher:\n    role: Caption Refresher\n    goal: Rewrite captions with fresh angles for recycled content\n    tools:\n      - ai:write\n    backstory: Creative copywriter specializing in content repurposing\n\n  reposter:\n    role: Reposter\n    goal: Republish selected content with new captions\n    tools:\n      - social:publish\n    backstory: Social media scheduler','\n',char(10)),replace('# Evergreen Content Recycle Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: top_performing_posts\nplatform: "{{config.platform}}"\nperiod: last_30_days\nlimit: 3\nmetric: engagement_rate\n```\n\n## Step 2: ai:write\n```yaml\ntask: refresh_captions\nposts: "{{step_1.output.posts}}"\nbrand_voice: "{{config.brand_voice}}"\navoid_duplicate_hooks: true\n```\n\n## Step 3: social:publish\n```yaml\nplatform: "{{config.platform}}"\nposts: "{{step_1.output.posts}}"\ncaptions: "{{step_2.output.captions}}"\nschedule: spread_over_month\n```','\n',char(10)),'{"type":"object","required":["recycledCount"],"properties":{"recycledCount":{"type":"integer"},"postIds":{"type":"array","items":{"type":"string"}}}}','{"properties":{"platform":{"type":"string","title":"Social platform","enum":["tiktok","instagram","youtube","twitter"],"default":"instagram"},"brand_voice":{"type":"string","title":"Brand voice","enum":["professional","casual","inspirational","witty"],"default":"casual"}},"required":[]}','{"platform":"instagram","brand_voice":"casual"}',5,0,4,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_daily_lead_enrichment','daily-lead-enrichment','Làm Giàu Lead Hàng Ngày','Daily Lead Enrichment','Tự động làm giàu 50 lead mỗi ngày phù hợp với hồ sơ khách hàng lý tưởng (ICP)','Auto-enrich 50 leads per day matching your Ideal Customer Profile (ICP)','leads',replace('agents:\n  lead_finder:\n    role: Lead Finder\n    goal: Find {{config.leads_per_day}} new leads matching ICP in {{config.target_industry}}\n    tools:\n      - lead:find\n    backstory: B2B prospecting specialist\n\n  lead_enricher:\n    role: Lead Enricher\n    goal: Enrich each lead with company data, contact info, and intent signals\n    tools:\n      - lead:enrich\n    backstory: Data enrichment expert using Apollo, Clearbit, and LinkedIn\n\n  lead_scorer:\n    role: Lead Scorer\n    goal: Score and tag leads by fit and intent\n    tools:\n      - lead:score\n    backstory: Revenue operations analyst','\n',char(10)),replace('# Daily Lead Enrichment Playbook\n\n## Step 1: lead:find\n```yaml\nindustry: "{{config.target_industry}}"\ncompany_size: "{{config.company_size}}"\nlocation: "{{config.location}}"\ntitle_keywords: "{{config.decision_maker_title}}"\nlimit: {{config.leads_per_day}}\nexclude_existing: true\n```\n\n## Step 2: lead:enrich\n```yaml\nleads: "{{step_1.output.leads}}"\nfields:\n  - company_revenue\n  - employee_count\n  - linkedin_url\n  - email\n  - phone\n  - tech_stack\n```\n\n## Step 3: lead:score\n```yaml\nenriched_leads: "{{step_2.output.enriched}}"\nicp_criteria:\n  industry: "{{config.target_industry}}"\n  company_size: "{{config.company_size}}"\n  decision_maker_title: "{{config.decision_maker_title}}"\ntag_hot_threshold: 80\n```','\n',char(10)),'{"type":"object","required":["enrichedCount","hotLeadsCount"],"properties":{"enrichedCount":{"type":"integer"},"hotLeadsCount":{"type":"integer"},"leads":{"type":"array","items":{"type":"object"}}}}','{"properties":{"target_industry":{"type":"string","title":"Target industry","placeholder":"e.g. SaaS, E-commerce, Real Estate"},"company_size":{"type":"string","title":"Company size","enum":["1-10","11-50","51-200","201-1000","1000+","any"],"default":"11-50"},"location":{"type":"string","title":"Location / Market","placeholder":"e.g. Vietnam, Southeast Asia, United States","default":"Vietnam"},"decision_maker_title":{"type":"string","title":"Decision-maker title keywords","placeholder":"e.g. CEO, Marketing Director, Founder","default":"CEO, Founder"},"leads_per_day":{"type":"integer","title":"Leads to find per run","default":50,"minimum":10,"maximum":200}},"required":["target_industry"]}','{"company_size":"11-50","location":"Vietnam","decision_maker_title":"CEO, Founder","leads_per_day":50}',5,1,8,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_reactive_form_lead','reactive-form-lead','Tự Động Phản Hồi Lead Từ Form','Reactive Form Lead Engine','Khi khách điền form → làm giàu dữ liệu → gửi email cá nhân hóa ngay lập tức','When visitor fills form → enrich lead data → send personalized email instantly','leads',replace('agents:\n  lead_enricher:\n    role: Lead Enricher\n    goal: Enrich incoming lead with company and contact data\n    tools:\n      - lead:enrich\n    backstory: Real-time lead enrichment specialist\n\n  personalization_writer:\n    role: Personalization Writer\n    goal: Write a personalized first-touch email for the lead\n    tools:\n      - ai:write\n    backstory: Conversion copywriter specializing in cold email\n\n  email_sender:\n    role: Email Sender\n    goal: Send personalized email within 5 minutes of form submission\n    tools:\n      - email:test\n    backstory: Email deliverability expert','\n',char(10)),replace('# Reactive Form Lead Playbook\n\nTriggered via webhook when a lead submits your contact form.\n\n## Step 1: lead:enrich\n```yaml\nemail: "{{trigger.body.email}}"\nname: "{{trigger.body.name}}"\ncompany: "{{trigger.body.company}}"\nfields:\n  - linkedin_url\n  - company_size\n  - industry\n  - tech_stack\n```\n\n## Step 2: ai:write\n```yaml\ntask: personalized_first_touch\nlead_name: "{{step_1.output.name}}"\ncompany: "{{step_1.output.company}}"\nindustry: "{{step_1.output.industry}}"\nsender_name: "{{config.sender_name}}"\nservice_offered: "{{config.service_description}}"\ntone: "{{config.email_tone}}"\n```\n\n## Step 3: email:test\n```yaml\nto: "{{step_1.output.email}}"\nfrom_name: "{{config.sender_name}}"\nsubject: "{{step_2.output.subject}}"\nbody: "{{step_2.output.body}}"\ntrack_opens: true\n```','\n',char(10)),'{"type":"object","required":["leadId","emailId"],"properties":{"leadId":{"type":"string"},"enriched":{"type":"object"},"emailId":{"type":"string"}}}','{"properties":{"sender_name":{"type":"string","title":"Your name (email sender)","placeholder":"e.g. Nguyen Van A"},"service_description":{"type":"string","title":"What service do you offer?","placeholder":"e.g. AI-powered social media management for restaurants"},"email_tone":{"type":"string","title":"Email tone","enum":["friendly","professional","direct","consultative"],"default":"friendly"}},"required":["sender_name","service_description"]}','{"email_tone":"friendly"}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_linkedin_outreach','linkedin-outreach','Gửi DM LinkedIn Tự Động (BETA)','LinkedIn DM Outreach (BETA)','Tự động gửi chuỗi tin nhắn LinkedIn đến danh sách khách tiềm năng — tính năng thử nghiệm','Auto-send LinkedIn DM sequences to prospect lists — BETA feature','leads',replace('agents:\n  message_writer:\n    role: Message Writer\n    goal: Write personalized LinkedIn DMs for {{config.target_role}} in {{config.target_industry}}\n    tools:\n      - ai:write\n    backstory: LinkedIn outreach copywriter with high acceptance rates\n\n  linkedin_sender:\n    role: LinkedIn Sender\n    goal: Send DMs via LinkedIn API (BETA)\n    tools:\n      - linkedin:send_message\n    backstory: LinkedIn automation specialist (BETA integration)','\n',char(10)),replace('# LinkedIn DM Outreach Playbook (BETA)\n\n> **BETA**: Requires LinkedIn API access. Contact support to enable.\n\n## Step 1: ai:write\n```yaml\ntask: linkedin_dm_sequence\ntarget_role: "{{config.target_role}}"\ntarget_industry: "{{config.target_industry}}"\nyour_value_prop: "{{config.value_proposition}}"\nsequence_steps: 3\ntone: conversational\navoid_salesy: true\n```\n\n## Step 2: linkedin:send_message\n```yaml\nrecipient_profile_url: "{{trigger.body.linkedin_url}}"\nmessage: "{{step_1.output.message_1}}"\nconnection_note: true\n```','\n',char(10)),'{"type":"object","required":["sentCount"],"properties":{"sentCount":{"type":"integer"},"messageIds":{"type":"array","items":{"type":"string"}}}}','{"properties":{"target_role":{"type":"string","title":"Target job title","placeholder":"e.g. Marketing Manager, CEO, Founder"},"target_industry":{"type":"string","title":"Target industry","placeholder":"e.g. Real Estate, E-commerce, Healthcare"},"value_proposition":{"type":"string","title":"Your value proposition","placeholder":"e.g. We help restaurants get 50+ new customers/month with AI marketing"}},"required":["target_role","value_proposition"]}','{}',10,0,5,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_cold_email_warmup','cold-email-warmup','Khởi Động Email Lạnh','Cold Email Warmup','Gửi 5 email mỗi ngày để làm ấm domain và tăng uy tín người gửi trước chiến dịch lớn','Send 5 warmup emails/day to build domain reputation before big campaigns','leads',replace('agents:\n  warmup_sender:\n    role: Warmup Sender\n    goal: Send {{config.daily_volume}} warmup emails to build sender reputation\n    tools:\n      - email:campaign\n    backstory: Email deliverability specialist\n\n  reputation_monitor:\n    role: Reputation Monitor\n    goal: Monitor open rates and spam scores from warmup emails\n    tools:\n      - analytics:report\n    backstory: Email analytics expert','\n',char(10)),replace('# Cold Email Warmup Playbook\n\n## Step 1: email:campaign\n```yaml\ntype: warmup\nfrom_email: "{{config.sender_email}}"\nfrom_name: "{{config.sender_name}}"\ndaily_volume: {{config.daily_volume}}\ncontent_variation: high\nreply_simulation: true\n```\n\n## Step 2: analytics:report\n```yaml\ntype: email_warmup_metrics\nemail_account: "{{config.sender_email}}"\nperiod: today\n```','\n',char(10)),'{"type":"object","required":["sentCount","reputationScore"],"properties":{"sentCount":{"type":"integer"},"reputationScore":{"type":"number"},"openRate":{"type":"number"}}}','{"properties":{"sender_email":{"type":"string","title":"Your sending email","format":"email","placeholder":"you@yourdomain.com"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. Nguyen Van A"},"daily_volume":{"type":"integer","title":"Warmup emails per day","default":5,"minimum":2,"maximum":20}},"required":["sender_email","sender_name"]}','{"daily_volume":5}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_icp_scoring','icp-scoring','Chấm Điểm Lead Theo ICP','ICP Lead Scoring','Tự động chấm điểm và gắn thẻ lead dựa trên tiêu chí hồ sơ khách hàng lý tưởng của bạn','Auto-score and tag leads against your Ideal Customer Profile criteria','leads',replace('agents:\n  icp_scorer:\n    role: ICP Scorer\n    goal: Score all unscored leads against ICP criteria\n    tools:\n      - lead:score\n    backstory: Revenue operations analyst specializing in ICP frameworks\n\n  lead_tagger:\n    role: Lead Tagger\n    goal: Apply hot/warm/cold tags based on scores\n    tools:\n      - lead:tag\n    backstory: CRM automation specialist','\n',char(10)),replace('# ICP Lead Scoring Playbook\n\n## Step 1: lead:score\n```yaml\nscope: unscored_leads\nicp_criteria:\n  target_industry: "{{config.target_industry}}"\n  company_size_min: {{config.company_size_min}}\n  company_size_max: {{config.company_size_max}}\n  title_keywords: "{{config.title_keywords}}"\n  geography: "{{config.geography}}"\nweights:\n  industry_match: 40\n  title_match: 30\n  size_match: 20\n  geography_match: 10\n```\n\n## Step 2: lead:tag\n```yaml\nscored_leads: "{{step_1.output.scored}}"\nrules:\n  - score_gte: 80\n    tag: hot_lead\n  - score_gte: 50\n    tag: warm_lead\n  - score_lt: 50\n    tag: cold_lead\n```','\n',char(10)),'{"type":"object","required":["scoredCount","hotCount"],"properties":{"scoredCount":{"type":"integer"},"hotCount":{"type":"integer"},"warmCount":{"type":"integer"},"coldCount":{"type":"integer"}}}','{"properties":{"target_industry":{"type":"string","title":"Target industry","placeholder":"e.g. SaaS, Retail, Healthcare"},"company_size_min":{"type":"integer","title":"Min company size (employees)","default":10,"minimum":1},"company_size_max":{"type":"integer","title":"Max company size (employees)","default":500,"minimum":1},"title_keywords":{"type":"string","title":"Decision-maker title keywords","placeholder":"CEO, Founder, Marketing Director","default":"CEO, Founder"},"geography":{"type":"string","title":"Target geography","placeholder":"e.g. Vietnam, Southeast Asia","default":"Vietnam"}},"required":["target_industry"]}','{"company_size_min":10,"company_size_max":500,"title_keywords":"CEO, Founder","geography":"Vietnam"}',8,0,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_welcome_drip_7day','welcome-drip-7day','Chuỗi Email Chào Mừng 7 Ngày','7-Day Welcome Email Drip','Tự động gửi 7 email chào mừng trong 7 ngày đầu sau khi khách đăng ký','Auto-send 7 welcome emails over 7 days to new subscribers','email',replace('agents:\n  sequence_writer:\n    role: Sequence Writer\n    goal: Write 7-day welcome email series for {{config.brand_name}}\n    tools:\n      - ai:write\n    backstory: Email copywriter specializing in onboarding sequences\n\n  drip_sender:\n    role: Drip Sender\n    goal: Queue and schedule 7 emails for new subscriber\n    tools:\n      - email:campaign\n    backstory: Email automation specialist','\n',char(10)),replace('# 7-Day Welcome Drip Playbook\n\nTriggered when a new subscriber joins via webhook.\n\n## Step 1: ai:write\n```yaml\ntask: welcome_drip_sequence\nbrand_name: "{{config.brand_name}}"\nproduct_description: "{{config.product_description}}"\nprimary_cta: "{{config.primary_cta}}"\nsubscriber_name: "{{trigger.body.name}}"\ndays: 7\ntone: "{{config.tone}}"\n```\n\n## Step 2: email:campaign\n```yaml\ntype: drip_sequence\nto: "{{trigger.body.email}}"\nfrom_name: "{{config.sender_name}}"\nsequence: "{{step_1.output.emails}}"\nstart_immediately: true\ninterval_days: 1\n```','\n',char(10)),'{"type":"object","required":["sequenceId","scheduledCount"],"properties":{"sequenceId":{"type":"string"},"scheduledCount":{"type":"integer"}}}','{"properties":{"brand_name":{"type":"string","title":"Brand / Company name","placeholder":"e.g. Sophia Agency"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. The Sophia Team"},"product_description":{"type":"string","title":"Briefly describe your product/service","placeholder":"e.g. AI automation tools for digital agencies"},"primary_cta":{"type":"string","title":"Primary call-to-action","placeholder":"e.g. Book a free strategy call, Start your free trial"},"tone":{"type":"string","title":"Email tone","enum":["friendly","professional","conversational","educational"],"default":"friendly"}},"required":["brand_name","sender_name","product_description"]}','{"tone":"friendly"}',10,0,5,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_reengagement_campaign','reengagement-campaign','Chiến Dịch Tái Kích Hoạt','Re-engagement Campaign','Tự động gửi 3 email để win-back các subscriber không hoạt động trong 30+ ngày','Auto-send 3-email win-back sequence to subscribers inactive for 30+ days','email',replace('agents:\n  inactive_finder:\n    role: Inactive Finder\n    goal: Find subscribers inactive for {{config.inactive_days}} days\n    tools:\n      - analytics:report\n    backstory: Email list hygiene specialist\n\n  winback_writer:\n    role: Winback Writer\n    goal: Write compelling win-back email sequence\n    tools:\n      - ai:write\n    backstory: Re-engagement copywriter with high re-activation rates\n\n  campaign_sender:\n    role: Campaign Sender\n    goal: Send win-back sequence to inactive list\n    tools:\n      - email:campaign\n    backstory: Email marketing automation specialist','\n',char(10)),replace('# Re-engagement Campaign Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: inactive_subscribers\ninactive_days: {{config.inactive_days}}\nlimit: {{config.batch_size}}\nexclude_unsubscribed: true\n```\n\n## Step 2: ai:write\n```yaml\ntask: winback_sequence\nbrand_name: "{{config.brand_name}}"\ninactive_days: {{config.inactive_days}}\noffer: "{{config.special_offer}}"\nemails_count: 3\nurgency: medium\n```\n\n## Step 3: email:campaign\n```yaml\ntype: drip_sequence\nrecipients: "{{step_1.output.subscribers}}"\nfrom_name: "{{config.sender_name}}"\nsequence: "{{step_2.output.emails}}"\ninterval_days: 3\nadd_unsubscribe_link: true\n```','\n',char(10)),'{"type":"object","required":["targetedCount","sequenceId"],"properties":{"targetedCount":{"type":"integer"},"sequenceId":{"type":"string"}}}','{"properties":{"brand_name":{"type":"string","title":"Brand name","placeholder":"e.g. Sophia Agency"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. The Sophia Team"},"inactive_days":{"type":"integer","title":"Inactive threshold (days)","default":30,"minimum":14,"maximum":180},"batch_size":{"type":"integer","title":"Max subscribers per run","default":100,"minimum":10,"maximum":500},"special_offer":{"type":"string","title":"Special win-back offer (optional)","placeholder":"e.g. 20% off, Free 30-min consultation","default":""}},"required":["brand_name","sender_name"]}','{"inactive_days":30,"batch_size":100,"special_offer":""}',7,0,4,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_weekly_newsletter','weekly-newsletter','Bản Tin Email Hàng Tuần','Weekly Newsletter','Tự động tổng hợp nội dung từ RSS và analytics để gửi bản tin email hàng tuần','Auto-curate content from RSS feeds and analytics to send weekly email newsletter','email',replace('agents:\n  content_curator:\n    role: Content Curator\n    goal: Curate 5 top articles relevant to {{config.niche}} this week\n    tools:\n      - analytics:report\n    backstory: Content curation specialist with editorial judgment\n\n  newsletter_writer:\n    role: Newsletter Writer\n    goal: Write engaging newsletter with curated content and brand commentary\n    tools:\n      - ai:write\n    backstory: Newsletter copywriter with high open-rate track record\n\n  newsletter_sender:\n    role: Newsletter Sender\n    goal: Send newsletter to all active subscribers\n    tools:\n      - email:campaign\n    backstory: Email delivery and scheduling specialist','\n',char(10)),replace('# Weekly Newsletter Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: rss_top_articles\nrss_feeds: "{{config.rss_feeds}}"\nniche: "{{config.niche}}"\nperiod: last_7_days\nlimit: 5\n```\n\n## Step 2: ai:write\n```yaml\ntask: newsletter\nbrand_name: "{{config.brand_name}}"\nniche: "{{config.niche}}"\narticles: "{{step_1.output.articles}}"\neditor_intro: "{{config.editor_intro}}"\ninclude_cta: true\ncta_text: "{{config.cta_text}}"\ntone: "{{config.tone}}"\n```\n\n## Step 3: email:campaign\n```yaml\ntype: newsletter\nfrom_name: "{{config.sender_name}}"\nsubject: "{{step_2.output.subject}}"\nhtml_body: "{{step_2.output.html}}"\nlist: active_subscribers\ntrack_opens: true\ntrack_clicks: true\n```','\n',char(10)),'{"type":"object","required":["campaignId","recipientCount"],"properties":{"campaignId":{"type":"string"},"recipientCount":{"type":"integer"},"subject":{"type":"string"}}}','{"properties":{"brand_name":{"type":"string","title":"Newsletter / Brand name","placeholder":"e.g. The Sophia Weekly"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. Nguyen Van A from Sophia"},"niche":{"type":"string","title":"Newsletter topic / niche","placeholder":"e.g. AI marketing, digital agency growth"},"rss_feeds":{"type":"string","title":"RSS feed URLs (comma-separated)","placeholder":"https://blog1.com/rss, https://blog2.com/feed"},"editor_intro":{"type":"string","title":"Editor intro paragraph","placeholder":"Brief weekly message from you to your readers","default":""},"cta_text":{"type":"string","title":"Call-to-action text","placeholder":"e.g. Book a free strategy session","default":""},"tone":{"type":"string","title":"Writing tone","enum":["professional","conversational","educational","witty"],"default":"conversational"}},"required":["brand_name","sender_name","niche"]}','{"editor_intro":"","cta_text":"","tone":"conversational"}',8,1,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_abandoned_cart_recovery','abandoned-cart-recovery','Thu Hồi Giỏ Hàng Bỏ Dở','Abandoned Cart Recovery','Tự động gửi 3 email khi khách hàng bỏ dở giỏ hàng để tăng tỷ lệ chuyển đổi','Auto-send 3-email sequence when cart is abandoned to recover lost revenue','email',replace('agents:\n  cart_analyzer:\n    role: Cart Analyzer\n    goal: Analyze abandoned cart contents and calculate lost value\n    tools:\n      - analytics:report\n    backstory: E-commerce analytics specialist\n\n  recovery_writer:\n    role: Recovery Writer\n    goal: Write 3-email cart recovery sequence with urgency and social proof\n    tools:\n      - ai:write\n    backstory: E-commerce copywriter specializing in cart abandonment recovery\n\n  email_sender:\n    role: Email Sender\n    goal: Send timed recovery emails to cart abandoner\n    tools:\n      - email:campaign\n    backstory: Email automation specialist','\n',char(10)),replace('# Abandoned Cart Recovery Playbook\n\nTriggered via webhook when cart abandonment is detected.\n\n## Step 1: analytics:report\n```yaml\ntype: cart_details\ncart_id: "{{trigger.body.cart_id}}"\ncustomer_email: "{{trigger.body.email}}"\n```\n\n## Step 2: ai:write\n```yaml\ntask: cart_recovery_sequence\ncustomer_name: "{{trigger.body.name}}"\ncart_items: "{{step_1.output.items}}"\ncart_value: "{{step_1.output.total}}"\nbrand_name: "{{config.brand_name}}"\ndiscount_offer: "{{config.recovery_discount}}"\nurgency_hours: 24\nemails_count: 3\n```\n\n## Step 3: email:campaign\n```yaml\ntype: drip_sequence\nto: "{{trigger.body.email}}"\nfrom_name: "{{config.sender_name}}"\nsequence: "{{step_2.output.emails}}"\ndelays_hours: [1, 24, 72]\n```','\n',char(10)),'{"type":"object","required":["sequenceId","scheduledCount"],"properties":{"sequenceId":{"type":"string"},"scheduledCount":{"type":"integer"},"cartValue":{"type":"number"}}}','{"properties":{"brand_name":{"type":"string","title":"Brand name","placeholder":"e.g. Sophia Shop"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. The Sophia Team"},"recovery_discount":{"type":"string","title":"Recovery discount offer (optional)","placeholder":"e.g. 10% off with code COMEBACK10, free shipping","default":""}},"required":["brand_name","sender_name"]}','{"recovery_discount":""}',7,0,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_birthday_milestone','birthday-milestone','Email Sinh Nhật & Kỷ Niệm','Birthday & Milestone Email','Tự động gửi email cá nhân hóa cho sinh nhật và ngày kỷ niệm của khách hàng','Auto-send personalized birthday and anniversary emails to customers','email',replace('agents:\n  milestone_finder:\n    role: Milestone Finder\n    goal: Find customers with upcoming birthdays or anniversaries today\n    tools:\n      - analytics:report\n    backstory: CRM data analyst\n\n  milestone_writer:\n    role: Milestone Writer\n    goal: Write personalized milestone emails with special offers\n    tools:\n      - ai:write\n    backstory: Relationship marketing copywriter\n\n  email_sender:\n    role: Email Sender\n    goal: Send personalized milestone emails\n    tools:\n      - email:campaign\n    backstory: Email automation specialist','\n',char(10)),replace('# Birthday & Milestone Email Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: upcoming_milestones\nmilestone_types:\n  - birthday\n  - customer_anniversary\nlookahead_days: 1\n```\n\n## Step 2: ai:write\n```yaml\ntask: milestone_emails\ncustomers: "{{step_1.output.customers}}"\nbrand_name: "{{config.brand_name}}"\ngift_offer: "{{config.birthday_offer}}"\ntone: warm_personal\n```\n\n## Step 3: email:campaign\n```yaml\ntype: individual_personalized\nemails: "{{step_2.output.emails}}"\nfrom_name: "{{config.sender_name}}"\nsend_at: morning\n```','\n',char(10)),'{"type":"object","required":["sentCount"],"properties":{"sentCount":{"type":"integer"},"milestoneTypes":{"type":"object"}}}','{"properties":{"brand_name":{"type":"string","title":"Brand name","placeholder":"e.g. Sophia Agency"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. The Sophia Team"},"birthday_offer":{"type":"string","title":"Birthday gift / offer","placeholder":"e.g. 20% birthday discount, free consultation","default":""}},"required":["brand_name","sender_name"]}','{"birthday_offer":""}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_proposal_auto_pilot_v2','proposal-auto-pilot-v2','Lái Tự Động Đề Xuất','Proposal Auto-Pilot','Hàng ngày tự động tìm 5 lead inbound, tạo đề xuất cá nhân hóa và gửi ngay','Daily: auto-find 5 inbound leads, create personalized proposals, and send immediately','sales',replace('agents:\n  lead_finder:\n    role: Lead Finder\n    goal: Find {{config.proposals_per_day}} inbound leads ready for proposals\n    tools:\n      - lead:find\n    backstory: Sales operations specialist\n\n  proposal_creator:\n    role: Proposal Creator\n    goal: Create personalized proposals for each lead\n    tools:\n      - proposal:create\n    backstory: Senior proposal writer with high win rates\n\n  proposal_sender:\n    role: Proposal Sender\n    goal: Send proposals via email with tracking\n    tools:\n      - email:campaign\n    backstory: Sales enablement specialist','\n',char(10)),replace('# Proposal Auto-Pilot Playbook\n\n## Step 1: lead:find\n```yaml\nstatus: inbound_qualified\nlimit: {{config.proposals_per_day}}\nsort_by: recency\n```\n\n## Step 2: proposal:create\n```yaml\nleads: "{{step_1.output.leads}}"\nservice_name: "{{config.service_name}}"\npricing_model: "{{config.pricing_model}}"\nstarting_price: {{config.starting_price}}\ncurrency: "{{config.currency}}"\ninclude_case_studies: true\n```\n\n## Step 3: email:campaign\n```yaml\ntype: individual_proposals\nproposals: "{{step_2.output.proposals}}"\nfrom_name: "{{config.sender_name}}"\nsubject_template: "Proposal for {{lead.company}} — {{service_name}}"\ntrack_opens: true\ntrack_link_clicks: true\n```','\n',char(10)),'{"type":"object","required":["proposals"],"properties":{"proposals":{"type":"array","items":{"type":"object","properties":{"proposalId":{"type":"string"},"leadId":{"type":"string"}},"required":["proposalId","leadId"]},"minItems":1}}}','{"properties":{"service_name":{"type":"string","title":"Service / product name","placeholder":"e.g. AI Social Media Management"},"sender_name":{"type":"string","title":"Your name (sender)","placeholder":"e.g. Nguyen Van A"},"pricing_model":{"type":"string","title":"Pricing model","enum":["fixed","monthly_retainer","hourly","performance"],"default":"monthly_retainer"},"starting_price":{"type":"integer","title":"Starting price","default":500,"minimum":0},"currency":{"type":"string","title":"Currency","enum":["USD","VND","EUR","SGD"],"default":"USD"},"proposals_per_day":{"type":"integer","title":"Proposals per day","default":5,"minimum":1,"maximum":20}},"required":["service_name","sender_name"]}','{"pricing_model":"monthly_retainer","starting_price":500,"currency":"USD","proposals_per_day":5}',5,1,5,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_quote_generator','quote-generator','Tạo Báo Giá Tự Động','Auto Quote Generator','Tự động tạo báo giá chuyên nghiệp khi nhận yêu cầu từ khách hàng qua webhook','Auto-generate professional quotes when customer request arrives via webhook','sales',replace('agents:\n  quote_calculator:\n    role: Quote Calculator\n    goal: Calculate quote based on products and quantities\n    tools:\n      - proposal:create\n    backstory: Pricing specialist with product catalog knowledge\n\n  quote_sender:\n    role: Quote Sender\n    goal: Send formatted quote PDF to customer\n    tools:\n      - email:campaign\n    backstory: Sales enablement specialist','\n',char(10)),replace('# Auto Quote Generator Playbook\n\nTriggered via webhook when quote request is received.\n\n## Step 1: proposal:create\n```yaml\ntype: quote\ncustomer_name: "{{trigger.body.customer_name}}"\ncustomer_email: "{{trigger.body.customer_email}}"\nitems: "{{trigger.body.items}}"\nservice_name: "{{config.service_name}}"\nbase_price: {{config.base_price}}\ncurrency: "{{config.currency}}"\nvalidity_days: {{config.quote_validity_days}}\ninclude_terms: true\ncompany_name: "{{config.company_name}}"\n```\n\n## Step 2: email:campaign\n```yaml\nto: "{{trigger.body.customer_email}}"\nfrom_name: "{{config.sender_name}}"\nsubject: "Quote #{{step_1.output.quoteNumber}} for {{trigger.body.customer_name}}"\nattach_pdf: "{{step_1.output.pdfUrl}}"\ntemplate: professional_quote\n```','\n',char(10)),'{"type":"object","required":["quoteId","emailId"],"properties":{"quoteId":{"type":"string"},"quoteNumber":{"type":"string"},"emailId":{"type":"string"},"totalAmount":{"type":"number"}}}','{"properties":{"company_name":{"type":"string","title":"Your company name","placeholder":"e.g. Sophia Agency Co., Ltd."},"service_name":{"type":"string","title":"Default service / product name","placeholder":"e.g. AI Marketing Package"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. Nguyen Van A — Sales"},"base_price":{"type":"integer","title":"Base unit price","default":100,"minimum":0},"currency":{"type":"string","title":"Currency","enum":["USD","VND","EUR","SGD"],"default":"USD"},"quote_validity_days":{"type":"integer","title":"Quote valid for (days)","default":14,"minimum":1,"maximum":90}},"required":["company_name","service_name","sender_name"]}','{"base_price":100,"currency":"USD","quote_validity_days":14}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_post_demo_followup','post-demo-followup','Theo Dõi Sau Demo','Post-Demo Follow-up','Chuỗi 5 email theo dõi sau khi khách hàng tham dự demo sản phẩm','5-touch email follow-up sequence after a product demo','sales',replace('agents:\n  followup_writer:\n    role: Followup Writer\n    goal: Write 5 post-demo follow-up emails for {{config.product_name}}\n    tools:\n      - ai:write\n    backstory: Sales copywriter with B2B closing expertise\n\n  sequence_sender:\n    role: Sequence Sender\n    goal: Send timed follow-up sequence to demo prospect\n    tools:\n      - email:campaign\n    backstory: Sales automation specialist','\n',char(10)),replace('# Post-Demo Follow-up Playbook\n\nTriggered via webhook after demo is completed.\n\n## Step 1: ai:write\n```yaml\ntask: post_demo_sequence\nprospect_name: "{{trigger.body.prospect_name}}"\ncompany: "{{trigger.body.company}}"\nproduct_name: "{{config.product_name}}"\ndemo_date: "{{trigger.body.demo_date}}"\npain_points_discussed: "{{trigger.body.pain_points}}"\nnext_step: "{{config.desired_next_step}}"\nemails_count: 5\ntone: professional_warm\n```\n\n## Step 2: email:campaign\n```yaml\ntype: drip_sequence\nto: "{{trigger.body.prospect_email}}"\nfrom_name: "{{config.sender_name}}"\nsequence: "{{step_1.output.emails}}"\ndelays_days: [0, 2, 5, 9, 14]\n```','\n',char(10)),'{"type":"object","required":["sequenceId","scheduledCount"],"properties":{"sequenceId":{"type":"string"},"scheduledCount":{"type":"integer"}}}','{"properties":{"product_name":{"type":"string","title":"Product / service name","placeholder":"e.g. Sophia AI Pro"},"sender_name":{"type":"string","title":"Sales rep name","placeholder":"e.g. Nguyen Van A"},"desired_next_step":{"type":"string","title":"Desired next step after demo","enum":["schedule_trial","send_proposal","book_call","start_now"],"default":"send_proposal"}},"required":["product_name","sender_name"]}','{"desired_next_step":"send_proposal"}',7,0,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_win_loss_analysis','win-loss-analysis','Phân Tích Thắng/Thua Tuần','Weekly Win/Loss Analysis','Hàng tuần phân tích các thương vụ đã đóng để tìm ra pattern thành công','Weekly analysis of closed deals to identify winning patterns and blockers','sales',replace('agents:\n  deal_analyst:\n    role: Deal Analyst\n    goal: Analyze this week closed/lost deals and identify patterns\n    tools:\n      - analytics:report\n    backstory: Revenue analytics expert with CRM expertise\n\n  insights_writer:\n    role: Insights Writer\n    goal: Write actionable win/loss report with recommendations\n    tools:\n      - ai:write\n    backstory: Business analyst and strategic advisor\n\n  report_sender:\n    role: Report Sender\n    goal: Send weekly win/loss report to sales team\n    tools:\n      - email:campaign\n    backstory: Sales operations coordinator','\n',char(10)),replace('# Weekly Win/Loss Analysis Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: closed_deals\nperiod: last_7_days\ninclude_fields:\n  - deal_size\n  - close_reason\n  - sales_cycle_days\n  - lead_source\n  - objections\n  - competitor\n```\n\n## Step 2: ai:write\n```yaml\ntask: win_loss_analysis\ndeals_data: "{{step_1.output.deals}}"\nwon_count: "{{step_1.output.won_count}}"\nlost_count: "{{step_1.output.lost_count}}"\nfocus_areas:\n  - top_win_reasons\n  - top_loss_reasons\n  - recommended_improvements\nteam_size: "{{config.team_size}}"\n```\n\n## Step 3: email:campaign\n```yaml\ntype: internal_report\nto: "{{config.report_recipients}}"\nfrom_name: "Sophia Sales Analytics"\nsubject: "Weekly Win/Loss Report — {{step_1.output.week_label}}"\nbody: "{{step_2.output.report}}"\n```','\n',char(10)),'{"type":"object","required":["reportId","wonCount","lostCount"],"properties":{"reportId":{"type":"string"},"wonCount":{"type":"integer"},"lostCount":{"type":"integer"},"winRate":{"type":"number"}}}','{"properties":{"report_recipients":{"type":"string","title":"Report recipients (comma-separated emails)","placeholder":"ceo@company.com, sales@company.com","format":"email"},"team_size":{"type":"integer","title":"Sales team size","default":1,"minimum":1,"maximum":100}},"required":["report_recipients"]}','{"team_size":1}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_daily_linkedin_post','daily-linkedin-post','Bài Đăng LinkedIn Mỗi Ngày','Daily LinkedIn Post','Tự động tạo và đăng 1 bài thought-leadership trên LinkedIn mỗi ngày','Auto-create and publish 1 thought-leadership LinkedIn post daily','social',replace('agents:\n  thought_leader_writer:\n    role: Thought Leader Writer\n    goal: Write a LinkedIn post establishing {{config.your_name}} as expert in {{config.expertise}}\n    tools:\n      - ai:write\n    backstory: B2B LinkedIn content strategist with 100K+ follower clients\n\n  linkedin_publisher:\n    role: LinkedIn Publisher\n    goal: Publish post to LinkedIn company or personal page\n    tools:\n      - social:publish\n    backstory: Social media scheduler specialist','\n',char(10)),replace('# Daily LinkedIn Post Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: trending_topics\nplatform: linkedin\nniche: "{{config.expertise}}"\nperiod: today\nlimit: 3\n```\n\n## Step 2: ai:write\n```yaml\ntask: linkedin_thought_leader_post\nauthor_name: "{{config.your_name}}"\nexpertise: "{{config.expertise}}"\ntrending_topic: "{{step_1.output.topics[0]}}"\npost_format: "{{config.post_format}}"\ninclude_cta: true\ncta_type: comment_engagement\ninclude_hashtags: true\n```\n\n## Step 3: social:publish\n```yaml\nplatform: linkedin\ncontent: "{{step_2.output.post}}"\nhashtags: "{{step_2.output.hashtags}}"\npublish_time: morning\n```','\n',char(10)),'{"type":"object","required":["postId"],"properties":{"postId":{"type":"string"},"linkedinUrl":{"type":"string"}}}','{"properties":{"your_name":{"type":"string","title":"Your name / personal brand","placeholder":"e.g. Nguyen Van A"},"expertise":{"type":"string","title":"Your area of expertise","placeholder":"e.g. AI marketing automation, digital agency growth"},"post_format":{"type":"string","title":"Post format","enum":["story","list_tips","opinion","case_study","question"],"default":"list_tips"}},"required":["your_name","expertise"]}','{"post_format":"list_tips"}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_weekly_twitter_thread','weekly-twitter-thread','Thread Twitter Hàng Tuần','Weekly Twitter Thread','Tự động tạo và đăng thread 8 tweet mỗi tuần để xây dựng thương hiệu cá nhân trên X','Auto-create and post 8-tweet thread weekly to build personal brand on X/Twitter','social',replace('agents:\n  thread_writer:\n    role: Thread Writer\n    goal: Write viral 8-tweet thread on {{config.topic_theme}} for {{config.author_handle}}\n    tools:\n      - ai:write\n    backstory: Twitter/X thread specialist with viral thread writing expertise\n\n  twitter_publisher:\n    role: Twitter Publisher\n    goal: Publish thread to Twitter/X account\n    tools:\n      - social:publish\n    backstory: Social media automation specialist','\n',char(10)),replace('# Weekly Twitter Thread Playbook\n\n## Step 1: ai:write\n```yaml\ntask: twitter_thread\ntopic_theme: "{{config.topic_theme}}"\nauthor_handle: "{{config.author_handle}}"\ntweet_count: {{config.tweet_count}}\nhook_style: "{{config.hook_style}}"\ninclude_cta_last_tweet: true\nformat: numbered_list\n```\n\n## Step 2: social:publish\n```yaml\nplatform: twitter\ntype: thread\ntweets: "{{step_1.output.tweets}}"\nschedule: tuesday_9am\n```','\n',char(10)),'{"type":"object","required":["threadId","tweetCount"],"properties":{"threadId":{"type":"string"},"tweetCount":{"type":"integer"},"firstTweetUrl":{"type":"string"}}}','{"properties":{"author_handle":{"type":"string","title":"Your Twitter/X handle","placeholder":"@yourbrand"},"topic_theme":{"type":"string","title":"Weekly topic theme","placeholder":"e.g. AI tools for agencies, growth hacking, startup lessons"},"tweet_count":{"type":"integer","title":"Number of tweets in thread","default":8,"minimum":5,"maximum":15},"hook_style":{"type":"string","title":"Hook tweet style","enum":["bold_claim","question","story","number_list","controversial"],"default":"bold_claim"}},"required":["author_handle","topic_theme"]}','{"tweet_count":8,"hook_style":"bold_claim"}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_tiktok_hook_ab_test','tiktok-hook-ab-test','A/B Test Hook TikTok','TikTok Hook A/B Test','Tự động tạo 5 biến thể hook cho video TikTok để tìm hook có hiệu suất cao nhất','Auto-generate 5 hook variants for TikTok videos to find the highest-performing hook','social',replace('agents:\n  hook_generator:\n    role: Hook Generator\n    goal: Generate 5 different TikTok hook styles for the same video topic\n    tools:\n      - ai:write\n    backstory: TikTok hook specialist who has analyzed 10,000+ viral videos\n\n  hook_analyzer:\n    role: Hook Analyzer\n    goal: Score each hook variant for virality potential\n    tools:\n      - analytics:report\n    backstory: Viral content analyst','\n',char(10)),replace('# TikTok Hook A/B Test Playbook\n\n## Step 1: ai:write\n```yaml\ntask: hook_variants\nvideo_topic: "{{config.video_topic}}"\ntarget_audience: "{{config.target_audience}}"\nniche: "{{config.niche}}"\nhook_styles:\n  - curiosity_gap\n  - bold_claim\n  - question\n  - shocking_stat\n  - story_opener\ncount_per_style: 1\nmax_words: 15\n```\n\n## Step 2: analytics:report\n```yaml\ntype: hook_virality_score\nhooks: "{{step_1.output.hooks}}"\nplatform: tiktok\naudience: "{{config.target_audience}}"\n```','\n',char(10)),'{"type":"object","required":["hooks","topHook"],"properties":{"hooks":{"type":"array","items":{"type":"object","properties":{"text":{"type":"string"},"style":{"type":"string"},"viralityScore":{"type":"number"}}}},"topHook":{"type":"string"}}}','{"properties":{"video_topic":{"type":"string","title":"Video topic","placeholder":"e.g. 5 ways AI saves agency owners 10 hours/week"},"niche":{"type":"string","title":"Content niche","placeholder":"e.g. business, fitness, finance, cooking"},"target_audience":{"type":"string","title":"Target audience","placeholder":"e.g. small business owners, college students"}},"required":["video_topic","niche"]}','{}',5,0,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_comment_auto_reply','comment-auto-reply','Tự Động Phản Hồi Bình Luận (BETA)','Comment Auto-Reply (BETA)','Tự động phân loại và phản hồi bình luận trên mạng xã hội bằng AI — tính năng thử nghiệm','Auto-classify and reply to social media comments using AI — BETA feature','social',replace('agents:\n  comment_fetcher:\n    role: Comment Fetcher\n    goal: Fetch new unanswered comments from connected platforms\n    tools:\n      - social:get_comments\n    backstory: Social media monitoring specialist (BETA)\n\n  reply_writer:\n    role: Reply Writer\n    goal: Write appropriate AI replies for each comment type\n    tools:\n      - ai:write\n    backstory: Community manager trained on brand voice guidelines\n\n  reply_publisher:\n    role: Reply Publisher\n    goal: Post replies to matching comments (BETA)\n    tools:\n      - social:reply_comment\n    backstory: Social media automation specialist (BETA)','\n',char(10)),replace('# Comment Auto-Reply Playbook (BETA)\n\n> **BETA**: Requires platform API access for comment reading/writing.\n> Currently supported: Instagram (business accounts), Facebook Pages.\n\n## Step 1: social:get_comments\n```yaml\nplatform: "{{config.platform}}"\nstatus: unanswered\nlimit: 20\nsentiment_filter: all\n```\n\n## Step 2: ai:write\n```yaml\ntask: comment_replies\ncomments: "{{step_1.output.comments}}"\nbrand_name: "{{config.brand_name}}"\nbrand_voice: "{{config.tone}}"\nreply_rules:\n  - type: question\n    strategy: helpful_answer\n  - type: complaint\n    strategy: empathetic_escalate\n  - type: compliment\n    strategy: grateful_engage\n  - type: spam\n    strategy: skip\n```\n\n## Step 3: social:reply_comment\n```yaml\nplatform: "{{config.platform}}"\nreplies: "{{step_2.output.replies}}"\nrequire_approval_for_complaints: {{config.approve_complaints}}\n```','\n',char(10)),'{"type":"object","required":["repliedCount"],"properties":{"repliedCount":{"type":"integer"},"skippedCount":{"type":"integer"},"pendingApprovalCount":{"type":"integer"}}}','{"properties":{"platform":{"type":"string","title":"Social platform","enum":["instagram","facebook"],"default":"instagram"},"brand_name":{"type":"string","title":"Brand name","placeholder":"e.g. Sophia Agency"},"tone":{"type":"string","title":"Reply tone","enum":["professional","friendly","casual","formal"],"default":"friendly"},"approve_complaints":{"type":"boolean","title":"Require approval before replying to complaints","default":true}},"required":["brand_name"]}','{"platform":"instagram","tone":"friendly","approve_complaints":true}',8,0,4,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_weekly_performance_report_v2','weekly-performance-report-v2','Báo Cáo Hiệu Suất Hàng Tuần','Weekly Performance Report','Tự động truy vấn analytics và gửi báo cáo tóm tắt hiệu suất hàng tuần qua email','Auto-query analytics and send weekly performance summary email to your team','analytics',replace('agents:\n  analytics_reporter:\n    role: Analytics Reporter\n    goal: Generate weekly performance metrics for {{config.report_scope}}\n    tools:\n      - analytics:report\n    backstory: Data analytics specialist\n\n  insights_writer:\n    role: Insights Writer\n    goal: Write executive summary with key insights and recommendations\n    tools:\n      - ai:write\n    backstory: Business intelligence writer\n\n  report_sender:\n    role: Report Sender\n    goal: Email the weekly report to stakeholders\n    tools:\n      - email:campaign\n    backstory: Report distribution specialist','\n',char(10)),replace('# Weekly Performance Report Playbook\n\n## Step 1: analytics:report\n```yaml\nscope: "{{config.report_scope}}"\nperiod: last_7_days\nmetrics:\n  - revenue\n  - leads_generated\n  - email_open_rate\n  - social_engagement\n  - video_views\n  - campaigns_sent\ncompare_to_previous: true\n```\n\n## Step 2: ai:write\n```yaml\ntask: executive_summary\nmetrics_data: "{{step_1.output.metrics}}"\nprevious_period: "{{step_1.output.previous}}"\nhighlights_count: 3\ninclude_recommendations: true\nformat: "{{config.report_format}}"\n```\n\n## Step 3: email:campaign\n```yaml\ntype: report\nto: "{{config.report_recipients}}"\nfrom_name: "Sophia Analytics"\nsubject: "Weekly Performance Report — {{step_1.output.week_label}}"\nhtml_body: "{{step_2.output.html}}"\n```','\n',char(10)),'{"type":"object","required":["reportId","emailId","metricsSnapshot"],"properties":{"reportId":{"type":"string"},"emailId":{"type":"string"},"metricsSnapshot":{"type":"object"}}}','{"properties":{"report_recipients":{"type":"string","title":"Report recipients (comma-separated emails)","placeholder":"you@company.com, manager@company.com"},"report_scope":{"type":"string","title":"Report scope","enum":["all_channels","social_only","email_only","leads_only","revenue_only"],"default":"all_channels"},"report_format":{"type":"string","title":"Report format","enum":["executive_brief","detailed","visual_charts"],"default":"executive_brief"}},"required":["report_recipients"]}','{"report_scope":"all_channels","report_format":"executive_brief"}',5,1,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_monthly_dashboard_pdf','monthly-dashboard-pdf','Báo Cáo PDF Tháng','Monthly Dashboard PDF','Tự động tạo và gửi email báo cáo hiệu suất PDF hàng tháng cho khách hàng hoặc nhóm','Auto-generate and email monthly performance PDF report to clients or team','analytics',replace('agents:\n  monthly_analyzer:\n    role: Monthly Analyzer\n    goal: Compile full month metrics and compare to previous month\n    tools:\n      - analytics:report\n    backstory: Business intelligence analyst\n\n  pdf_generator:\n    role: PDF Generator\n    goal: Generate professional PDF dashboard with charts\n    tools:\n      - report:generate_pdf\n    backstory: Data visualization and report design specialist\n\n  pdf_sender:\n    role: PDF Sender\n    goal: Email PDF report to client or internal team\n    tools:\n      - email:campaign\n    backstory: Client communication specialist','\n',char(10)),replace('# Monthly Dashboard PDF Playbook\n\n## Step 1: analytics:report\n```yaml\nperiod: last_30_days\ncompare_previous: true\ninclude_channels:\n  - social_media\n  - email_campaigns\n  - leads\n  - revenue\ngroup_by: week\n```\n\n## Step 2: report:generate_pdf\n```yaml\nreport_data: "{{step_1.output.metrics}}"\ntitle: "{{config.report_title}}"\nbrand_color: "{{config.brand_color}}"\nlogo_url: "{{config.logo_url}}"\ninclude_charts: true\nsections:\n  - executive_summary\n  - channel_breakdown\n  - goals_progress\n  - recommendations\n```\n\n## Step 3: email:campaign\n```yaml\nto: "{{config.report_recipients}}"\nfrom_name: "{{config.sender_name}}"\nsubject: "{{config.report_title}} — {{step_1.output.month_label}}"\nbody: "Please find attached your monthly performance report."\nattachment_url: "{{step_2.output.pdfUrl}}"\n```','\n',char(10)),'{"type":"object","required":["pdfUrl","emailId"],"properties":{"pdfUrl":{"type":"string"},"emailId":{"type":"string"},"month":{"type":"string"}}}','{"properties":{"report_title":{"type":"string","title":"Report title","default":"Monthly Performance Report","placeholder":"e.g. Sophia Agency Monthly Report"},"sender_name":{"type":"string","title":"Sender name","placeholder":"e.g. Sophia Analytics Team"},"report_recipients":{"type":"string","title":"Recipients (comma-separated emails)","placeholder":"client@company.com, you@agency.com"},"brand_color":{"type":"string","title":"Brand color (hex)","placeholder":"#6d28d9","default":"#6d28d9"},"logo_url":{"type":"string","title":"Company logo URL","placeholder":"https://your-site.com/logo.png","default":""}},"required":["sender_name","report_recipients"]}','{"report_title":"Monthly Performance Report","brand_color":"#6d28d9","logo_url":""}',7,0,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_daily_anomaly_alerts','daily-anomaly-alerts','Cảnh Báo Bất Thường Hàng Ngày','Daily Anomaly Alerts','Phát hiện sự thay đổi bất thường trong các chỉ số quan trọng và gửi cảnh báo ngay lập tức','Detect unusual drops or spikes in key metrics and send instant alerts','analytics',replace('agents:\n  anomaly_detector:\n    role: Anomaly Detector\n    goal: Scan key metrics for unusual changes vs 7-day baseline\n    tools:\n      - analytics:report\n    backstory: Statistical anomaly detection specialist\n\n  alert_writer:\n    role: Alert Writer\n    goal: Write clear alert message with root cause hypothesis\n    tools:\n      - ai:write\n    backstory: Technical writer specializing in operational alerts\n\n  alert_sender:\n    role: Alert Sender\n    goal: Send critical alerts to configured channels\n    tools:\n      - email:campaign\n    backstory: Incident notification specialist','\n',char(10)),replace('# Daily Anomaly Alerts Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: anomaly_detection\nmetrics: "{{config.monitored_metrics}}"\nbaseline_days: 7\nthreshold_percentage: {{config.alert_threshold}}\ninclude_charts: true\n```\n\n## Step 2: ai:write\n```yaml\ntask: anomaly_alert_message\nanomalies: "{{step_1.output.anomalies}}"\ncontext: "{{step_1.output.baseline}}"\ninclude_hypothesis: true\nurgency_level: "{{step_1.output.max_severity}}"\n```\n\n## Step 3: email:campaign\n```yaml\nto: "{{config.alert_recipients}}"\nfrom_name: "Sophia Monitoring"\nsubject: "⚠️ Anomaly Detected — {{step_1.output.anomaly_summary}}"\nbody: "{{step_2.output.alert_message}}"\npriority: high\n```','\n',char(10)),'{"type":"object","required":["anomalyCount","alertSent"],"properties":{"anomalyCount":{"type":"integer"},"alertSent":{"type":"boolean"},"severity":{"type":"string","enum":["low","medium","high","critical"]}}}','{"properties":{"alert_recipients":{"type":"string","title":"Alert recipients (comma-separated emails)","placeholder":"you@company.com"},"monitored_metrics":{"type":"string","title":"Metrics to monitor (comma-separated)","default":"revenue,leads,email_open_rate,social_engagement","placeholder":"revenue,leads,email_open_rate"},"alert_threshold":{"type":"integer","title":"Alert threshold (% change)","description":"Send alert when metric changes by more than this %","default":20,"minimum":5,"maximum":80}},"required":["alert_recipients"]}','{"monitored_metrics":"revenue,leads,email_open_rate,social_engagement","alert_threshold":20}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_mention_monitor_respond','mention-monitor-respond','Theo Dõi & Phản Hồi Đề Cập','Brand Mention Monitor & Respond','Theo dõi đề cập thương hiệu và soạn thảo phản hồi — yêu cầu phê duyệt trước khi gửi','Monitor brand mentions and draft responses — requires human approval before sending','crisis',replace('agents:\n  mention_monitor:\n    role: Mention Monitor\n    goal: Detect all mentions of {{config.brand_name}} across platforms\n    tools:\n      - analytics:report\n    backstory: Brand monitoring specialist with cross-platform coverage\n\n  sentiment_classifier:\n    role: Sentiment Classifier\n    goal: Classify mentions by sentiment and urgency level\n    tools:\n      - ai:write\n    backstory: Sentiment analysis expert\n\n  response_drafter:\n    role: Response Drafter\n    goal: Draft appropriate responses for negative mentions\n    tools:\n      - proposal:create\n    backstory: Crisis communication specialist and PR expert','\n',char(10)),replace('# Brand Mention Monitor & Respond Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: brand_mentions\nkeywords:\n  - "{{config.brand_name}}"\n  - "{{config.brand_aliases}}"\nplatforms:\n  - google\n  - facebook\n  - twitter\n  - tiktok\nperiod: last_24_hours\nsentiment: all\n```\n\n## Step 2: ai:write\n```yaml\ntask: classify_mentions\nmentions: "{{step_1.output.mentions}}"\nseverity_levels:\n  critical: ["lawsuit", "scam", "fraud", "complaint"]\n  high: ["negative review", "bad experience", "disappointed"]\n  low: ["question", "neutral mention"]\n```\n\n## Step 3: proposal:create\n```yaml\ntype: crisis_response_drafts\nclassified_mentions: "{{step_2.output.classified}}"\nbrand_name: "{{config.brand_name}}"\nresponse_tone: "{{config.response_tone}}"\nescalate_critical: true\nrequires_approval: true\n```','\n',char(10)),'{"type":"object","required":["mentionsReport","draftResponseId","requiresApproval"],"properties":{"mentionsReport":{"type":"object"},"draftResponseId":{"type":"string"},"requiresApproval":{"type":"boolean","const":true},"criticalCount":{"type":"integer"}}}','{"properties":{"brand_name":{"type":"string","title":"Brand name to monitor","placeholder":"e.g. Sophia Agency"},"brand_aliases":{"type":"string","title":"Brand aliases / variations (comma-separated)","placeholder":"e.g. SophiaAI, Sophia.ai, @sophia_agency","default":""},"response_tone":{"type":"string","title":"Crisis response tone","enum":["professional_empathetic","formal","friendly_resolving"],"default":"professional_empathetic"},"alert_recipients":{"type":"string","title":"Alert recipients for critical mentions","placeholder":"ceo@company.com, pr@company.com"}},"required":["brand_name"]}','{"brand_aliases":"","response_tone":"professional_empathetic"}',5,1,3,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_official_negative_review_classify','negative-review-classify','Phân Loại Đánh Giá Tiêu Cực','Negative Review Classifier','Tự động phân loại đánh giá tiêu cực và gửi cảnh báo ngay khi có review nghiêm trọng','Auto-classify negative reviews and instantly alert team when critical reviews appear','crisis',replace('agents:\n  review_fetcher:\n    role: Review Fetcher\n    goal: Fetch new reviews from Google, Facebook, and other platforms\n    tools:\n      - analytics:report\n    backstory: Review monitoring specialist\n\n  review_classifier:\n    role: Review Classifier\n    goal: Classify reviews by severity and category\n    tools:\n      - ai:write\n    backstory: Sentiment analysis and review categorization expert\n\n  alert_sender:\n    role: Alert Sender\n    goal: Send critical review alerts to team\n    tools:\n      - email:campaign\n    backstory: Customer experience operations specialist','\n',char(10)),replace('# Negative Review Classifier Playbook\n\n## Step 1: analytics:report\n```yaml\ntype: new_reviews\nbrand_name: "{{config.brand_name}}"\nplatforms:\n  - google_business\n  - facebook\n  - tripadvisor\nperiod: last_24_hours\nrating_filter: negative\n```\n\n## Step 2: ai:write\n```yaml\ntask: classify_reviews\nreviews: "{{step_1.output.reviews}}"\ncategories:\n  - service_quality\n  - product_defect\n  - delivery_issue\n  - pricing_complaint\n  - staff_behavior\nseverity_mapping:\n  1_star: critical\n  2_star: high\n  3_star: medium\nsuggest_response: true\n```\n\n## Step 3: email:campaign\n```yaml\ntype: review_alert\nto: "{{config.alert_recipients}}"\nfrom_name: "Sophia Review Monitor"\nsubject: "⚠️ {{step_1.output.new_count}} New Negative Reviews — Action Required"\nreviews_with_suggestions: "{{step_2.output.classified}}"\ninclude_response_drafts: true\n```','\n',char(10)),'{"type":"object","required":["reviewCount","criticalCount"],"properties":{"reviewCount":{"type":"integer"},"criticalCount":{"type":"integer"},"categories":{"type":"object"},"alertSent":{"type":"boolean"}}}','{"properties":{"brand_name":{"type":"string","title":"Business name to monitor","placeholder":"e.g. Sophia Agency"},"alert_recipients":{"type":"string","title":"Alert recipients (comma-separated)","placeholder":"manager@company.com, customer-service@company.com"},"min_severity_to_alert":{"type":"string","title":"Minimum severity to trigger alert","enum":["critical","high","medium"],"default":"high"}},"required":["brand_name","alert_recipients"]}','{"min_severity_to_alert":"high"}',5,0,2,1,1,NULL,'published',1777786945,1777786945);
INSERT INTO "sop_templates" ("id","slug","name_vi","name_en","description_vi","description_en","category","agents_yaml","playbook_md","output_schema","config_schema","config_defaults","setup_time_minutes","is_featured","credits_per_run","version","is_official","author_user_id","status","created_at","updated_at") VALUES('sop_starter_video_generation_v1','video-generation-starter','Tạo & Phân Phối Video AI Đầu Tiên','Generate & Distribute Your First AI Video','Tạo video AI từ prompt văn bản, ghép giọng đọc, sau đó tự động phân phối lên kênh đã kết nối','Generate an AI avatar video from a text prompt, add voiceover, then auto-distribute to your connected channels','content',replace('agents:\n  script_writer:\n    role: Script Writer\n    goal: Write a short engaging video script for {{config.topic}}\n    tools:\n      - ai:write\n    backstory: Short-form video copywriter specialising in AI-powered content\n\n  video_producer:\n    role: Video Producer\n    goal: Produce an AI avatar video using the generated script\n    tools:\n      - video:create\n    backstory: AI video production specialist using avatar synthesis\n\n  distributor:\n    role: Content Distributor\n    goal: Publish the finished video to all connected channels\n    tools:\n      - social:publish\n    backstory: Multi-channel distribution expert','\n',char(10)),replace('# Generate & Distribute Your First AI Video\n\n## Step 1: ai:write\n```yaml\ntask: video_script\ntopic: "{{config.topic}}"\ntone: "{{config.tone}}"\nduration_seconds: 60\nlanguage: "{{config.language}}"\ninclude_cta: true\n```\n\n## Step 2: video:create\n```yaml\nscript: "{{step_1.output.script}}"\navatar_id: default\nvoiceover_language: "{{config.language}}"\nformat: vertical_9x16\nduration: 60\n```\n\n## Step 3: social:publish\n```yaml\nplatform: all_connected\nvideo_id: "{{step_2.output.videoId}}"\ncaption: "{{step_1.output.caption}}"\nhashtags: "{{step_1.output.hashtags}}"\nschedule: now\n```','\n',char(10)),'{"type":"object","required":["videoId","publishedChannels"],"properties":{"videoId":{"type":"string"},"publishedChannels":{"type":"array","items":{"type":"string"}}}}','{"properties":{"topic":{"type":"string","title":"Video topic","description":"What is your video about?","placeholder":"e.g. How AI helps agencies save 10 hours per week"},"tone":{"type":"string","title":"Tone","enum":["professional","casual","educational","inspiring"],"default":"professional"},"language":{"type":"string","title":"Script language","enum":["en","vi"],"default":"en"}},"required":["topic"]}','{"tone":"professional","language":"en"}',3,1,5,2,1,NULL,'published',1779173456,1779238226);
