PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT,
  full_name TEXT,
  avatar_url TEXT,
  role TEXT DEFAULT 'user',
  email_verified INTEGER DEFAULT 0,
  magic_link_token TEXT,
  magic_link_expires_at TEXT,
  last_sign_in_at TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE organizations (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  name TEXT NOT NULL,
  slug TEXT UNIQUE,
  plan TEXT DEFAULT 'free',
  settings TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, email TEXT);
CREATE TABLE org_balances (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT UNIQUE NOT NULL REFERENCES organizations(id),
  balance REAL DEFAULT 0,
  updated_at TEXT DEFAULT (datetime('now'))
, reserved INTEGER NOT NULL DEFAULT 0, lifetime_credits INTEGER NOT NULL DEFAULT 0, lifetime_debits INTEGER NOT NULL DEFAULT 0);
CREATE TABLE transactions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  amount REAL NOT NULL,
  type TEXT NOT NULL,
  description TEXT,
  reference_id TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE billing_settings (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT UNIQUE NOT NULL REFERENCES organizations(id),
  billing_email TEXT,
  tax_id TEXT,
  settings TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, polar_customer_id TEXT);
CREATE TABLE usage_logs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  feature TEXT NOT NULL,
  quantity REAL DEFAULT 1,
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE missions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  title TEXT NOT NULL,
  command TEXT NOT NULL,
  params TEXT DEFAULT '{}',
  priority TEXT DEFAULT 'normal',
  status TEXT DEFAULT 'queued',
  result TEXT,
  error_message TEXT,
  mcu_cost REAL DEFAULT 0,
  mcu_reserved REAL DEFAULT 0,
  webhook_url TEXT,
  parent_mission_id TEXT,
  started_at TEXT,
  completed_at TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, execution_log TEXT DEFAULT '[]', max_retries INTEGER DEFAULT 3, retry_count INTEGER DEFAULT 0, description TEXT DEFAULT '', byok_provider_id TEXT, byok_model_id TEXT);
CREATE TABLE mission_templates (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  command TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  mcu_cost REAL DEFAULT 0,
  params_schema TEXT DEFAULT '{}',
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE mission_dependencies (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  mission_id TEXT NOT NULL REFERENCES missions(id),
  depends_on_mission_id TEXT NOT NULL REFERENCES missions(id),
  dependency_type TEXT DEFAULT 'sequential',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE mission_retries (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  mission_id TEXT NOT NULL REFERENCES missions(id),
  attempt_number INTEGER NOT NULL,
  error_message TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE scheduled_tasks (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  type TEXT NOT NULL,
  payload TEXT DEFAULT '{}',
  status TEXT DEFAULT 'pending',
  scheduled_for TEXT NOT NULL,
  executed_at TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE raas_api_keys (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  name TEXT NOT NULL,
  key_hash TEXT UNIQUE NOT NULL,
  key_prefix TEXT NOT NULL,
  permissions TEXT DEFAULT '["missions:create","missions:read"]',
  rate_limit_per_minute INTEGER DEFAULT 60,
  is_active INTEGER DEFAULT 1,
  last_used_at TEXT,
  expires_at TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE raas_api_usage (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  api_key_id TEXT NOT NULL,
  org_id TEXT NOT NULL,
  endpoint TEXT NOT NULL,
  method TEXT NOT NULL,
  status_code INTEGER,
  mcu_consumed REAL DEFAULT 0,
  response_time_ms INTEGER,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE raas_webhook_deliveries (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  mission_id TEXT NOT NULL,
  org_id TEXT NOT NULL,
  webhook_url TEXT NOT NULL,
  payload TEXT,
  status_code INTEGER,
  attempt_number INTEGER DEFAULT 1,
  delivered_at TEXT,
  next_retry_at TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE proposals (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  user_id TEXT,
  title TEXT NOT NULL,
  content TEXT,
  status TEXT DEFAULT 'draft',
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, mission_id TEXT, niche TEXT);
CREATE TABLE contacts (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  email TEXT,
  name TEXT,
  company TEXT,
  phone TEXT,
  source TEXT,
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE deals (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  contact_id TEXT REFERENCES contacts(id),
  title TEXT NOT NULL,
  value REAL DEFAULT 0,
  stage TEXT DEFAULT 'lead',
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE crm_settings (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT UNIQUE NOT NULL REFERENCES organizations(id),
  hubspot_access_token TEXT,
  hubspot_refresh_token TEXT,
  sync_enabled INTEGER DEFAULT 0,
  settings TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE crm_sync_status (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  last_synced_at TEXT,
  status TEXT DEFAULT 'idle',
  error_message TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE onboarding_progress (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  user_id TEXT,
  step TEXT NOT NULL,
  status TEXT DEFAULT 'pending',
  data TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE onboarding_events (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE onboarding_milestones (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  milestone TEXT NOT NULL,
  achieved_at TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE onboarding_calls (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  scheduled_at TEXT,
  completed_at TEXT,
  notes TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE pilot_onboarding (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  stage TEXT DEFAULT 'intake',
  checklist TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE referral_codes (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  user_id TEXT,
  code TEXT UNIQUE NOT NULL,
  uses INTEGER DEFAULT 0,
  max_uses INTEGER,
  reward_amount REAL DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE referral_events (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  referral_code_id TEXT NOT NULL,
  referred_org_id TEXT,
  event_type TEXT NOT NULL,
  amount REAL DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE affiliate_programs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  name TEXT NOT NULL,
  url TEXT,
  commission_rate REAL,
  status TEXT DEFAULT 'active',
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, is_active INTEGER DEFAULT 1, score REAL DEFAULT 0, niche TEXT DEFAULT '', description TEXT DEFAULT '', signup_url TEXT DEFAULT '', cookie_days INTEGER DEFAULT 30, payout_threshold REAL DEFAULT 0, payout_frequency TEXT DEFAULT 'monthly');
CREATE TABLE affiliate_content (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  program_id TEXT REFERENCES affiliate_programs(id),
  title TEXT,
  content TEXT,
  type TEXT DEFAULT 'post',
  status TEXT DEFAULT 'draft',
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE affiliate_clicks (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  program_id TEXT,
  content_id TEXT,
  url TEXT,
  referrer TEXT,
  ip_address TEXT,
  user_agent TEXT,
  created_at TEXT DEFAULT (datetime('now'))
, ip_hash TEXT DEFAULT '');
CREATE TABLE affiliate_payouts (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  program_id TEXT,
  amount REAL DEFAULT 0,
  status TEXT DEFAULT 'pending',
  paid_at TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE customer_feedback (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL,
  user_id TEXT,
  type TEXT DEFAULT 'general',
  rating INTEGER,
  message TEXT,
  metadata TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE scheduled_emails (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT,
  to_email TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  status TEXT DEFAULT 'pending',
  scheduled_for TEXT,
  sent_at TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE demo_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  company TEXT DEFAULT '',
  message TEXT DEFAULT '',
  status TEXT DEFAULT 'pending',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE mission_steps (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  mission_id TEXT NOT NULL REFERENCES missions(id) ON DELETE CASCADE,
  step_name TEXT NOT NULL,
  step_index INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'running', 'completed', 'failed', 'skipped')),
  output TEXT,
  error_message TEXT,
  started_at TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE leads (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  org_id TEXT NOT NULL,
  company_name TEXT NOT NULL,
  industry TEXT,
  estimated_size TEXT,
  decision_maker_title TEXT,
  pain_points TEXT, -- JSON array
  fit_score INTEGER DEFAULT 0,
  approach_angle TEXT,
  suggested_first_touch TEXT,
  source TEXT DEFAULT 'lead-hunter-ai',
  status TEXT DEFAULT 'new', -- new, contacted, qualified, converted, lost
  email TEXT,
  notes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (org_id) REFERENCES organizations(id)
);
CREATE TABLE email_outreach (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  org_id TEXT NOT NULL,
  lead_id TEXT,
  mission_id TEXT,
  to_email TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT,
  status TEXT DEFAULT 'sent', -- sent, delivered, opened, clicked, bounced
  provider TEXT DEFAULT 'resend',
  message_id TEXT,
  sequence_day INTEGER,
  sent_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (org_id) REFERENCES organizations(id),
  FOREIGN KEY (lead_id) REFERENCES leads(id),
  FOREIGN KEY (mission_id) REFERENCES missions(id)
);
CREATE TABLE blog_posts (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  excerpt TEXT,
  content TEXT NOT NULL,
  author TEXT DEFAULT 'Sophia AI',
  tags TEXT DEFAULT '[]',
  published INTEGER DEFAULT 0,
  published_at TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE health_checks (
  id        TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  status    TEXT NOT NULL,        -- 'ok' | 'degraded' | 'error'
  latency_ms INTEGER NOT NULL,    -- response time in milliseconds
  details   TEXT,                 -- JSON payload from /api/health/deep
  checked_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE campaigns ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL, title TEXT NOT NULL, topic TEXT DEFAULT '', audience TEXT DEFAULT '', status TEXT DEFAULT 'queued', progress INTEGER DEFAULT 0, template_id TEXT, script TEXT, video_url TEXT, thumbnail_url TEXT, platforms TEXT DEFAULT '[]', created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')) , org_id TEXT);
CREATE TABLE user_profiles ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL UNIQUE, subscription_tier TEXT DEFAULT 'BASIC', display_name TEXT, avatar_url TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')) , onboarding_completed_at INTEGER);
CREATE TABLE campaign_templates ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), name TEXT NOT NULL, description TEXT, tone TEXT DEFAULT 'casual', duration INTEGER DEFAULT 15, is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE user_sessions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL, token TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE audit_logs ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT, action TEXT NOT NULL, resource TEXT, details TEXT, ip_address TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE user_integrations ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL, provider TEXT NOT NULL, access_token TEXT, refresh_token TEXT, expires_at TEXT, metadata TEXT DEFAULT '{}', created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE payment_events ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), org_id TEXT NOT NULL, provider TEXT DEFAULT 'nowpayments', event_type TEXT NOT NULL, amount REAL, currency TEXT DEFAULT 'USD', status TEXT DEFAULT 'pending', metadata TEXT DEFAULT '{}', created_at TEXT DEFAULT (datetime('now')) , receipt_sent INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS "user" (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  email TEXT UNIQUE NOT NULL,
  emailVerified INTEGER DEFAULT 0,
  name TEXT,
  image TEXT,
  role TEXT DEFAULT 'user',
  createdAt TEXT DEFAULT (datetime('now')),
  updatedAt TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "session" (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  userId TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  expiresAt TEXT NOT NULL,
  token TEXT UNIQUE NOT NULL,
  ipAddress TEXT,
  userAgent TEXT,
  createdAt TEXT DEFAULT (datetime('now')),
  updatedAt TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "account" (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  userId TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  accountId TEXT NOT NULL,
  providerId TEXT NOT NULL,
  accessToken TEXT,
  refreshToken TEXT,
  expiresAt TEXT,
  password TEXT,
  scope TEXT,
  createdAt TEXT DEFAULT (datetime('now')),
  updatedAt TEXT DEFAULT (datetime('now')),
  UNIQUE(providerId, accountId)
);
CREATE TABLE IF NOT EXISTS "verification" (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  identifier TEXT NOT NULL,
  value TEXT NOT NULL,
  expiresAt TEXT NOT NULL,
  createdAt TEXT DEFAULT (datetime('now')),
  updatedAt TEXT DEFAULT (datetime('now'))
);
CREATE TABLE error_log (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  ts        TEXT    NOT NULL,           -- ISO-8601 UTC timestamp
  level     TEXT    NOT NULL,           -- 'error' | 'fatal'
  msg       TEXT    NOT NULL,           -- normalized, PII-scrubbed message (≤500 chars)
  msg_class TEXT    NOT NULL,           -- error constructor name (e.g. 'TypeError')
  fingerprint TEXT  NOT NULL,           -- sha256(normalizedMsg + ':' + msgClass)
  ctx_json  TEXT    NOT NULL DEFAULT '{}', -- scrubbed context JSON
  commit_sha TEXT   NOT NULL DEFAULT 'unknown', -- COMMIT_SHA from env (P1) — `commit` is reserved keyword
  route     TEXT    NOT NULL DEFAULT '', -- originating API route
  status    INTEGER NOT NULL DEFAULT 500 -- HTTP status at time of error
);
CREATE TABLE rate_limits (
  identifier TEXT PRIMARY KEY,
  current_count INTEGER NOT NULL DEFAULT 0,
  window_start TEXT NOT NULL DEFAULT (datetime('now')),
  window_seconds INTEGER NOT NULL DEFAULT 60,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE export_jobs (
  id TEXT PRIMARY KEY,
  org_id TEXT REFERENCES organizations(id),
  license_nonce TEXT NOT NULL,           -- raas_licenses.nonce
  export_format TEXT NOT NULL DEFAULT 'json',  -- 'json' | 'csv'
  period_start INTEGER NOT NULL,         -- Unix seconds (start of export window)
  period_end INTEGER NOT NULL,           -- Unix seconds (end of export window)
  record_count INTEGER NOT NULL DEFAULT 0,
  success INTEGER NOT NULL DEFAULT 0,    -- SQLite boolean: 1=true, 0=false
  error_message TEXT,
  created_at INTEGER NOT NULL            -- Unix seconds (set by route.ts)
);
CREATE TABLE agent_teams (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT UNIQUE NOT NULL REFERENCES organizations(id),
  name TEXT NOT NULL DEFAULT 'My AI Company',
  config TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE agents (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  team_id TEXT NOT NULL REFERENCES agent_teams(id),
  role TEXT NOT NULL CHECK (role IN ('CEO','Developer')),
  name TEXT NOT NULL,
  system_prompt TEXT NOT NULL,
  model TEXT DEFAULT 'openai/gpt-4o-mini',
  enabled INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE agent_tasks (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  agent_id TEXT NOT NULL REFERENCES agents(id),
  input TEXT NOT NULL,
  output TEXT,
  status TEXT DEFAULT 'queued'
    CHECK (status IN ('queued','running','completed','failed')),
  error_message TEXT,
  tokens_used INTEGER DEFAULT 0,
  cost_usd REAL DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  completed_at TEXT
);
CREATE TABLE agent_logs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  task_id TEXT NOT NULL REFERENCES agent_tasks(id),
  action TEXT NOT NULL,
  payload TEXT DEFAULT '{}',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE cron_run_log (
  cron_name TEXT PRIMARY KEY,
  last_run_at INTEGER NOT NULL DEFAULT (unixepoch()),
  last_status TEXT NOT NULL DEFAULT 'unknown',
  last_error TEXT,
  run_count INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE audit_log (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  table_name TEXT    NOT NULL,
  row_id     TEXT    NOT NULL,
  action     TEXT    NOT NULL CHECK (action IN ('insert', 'update', 'delete')),
  actor_id   TEXT,
  before_json TEXT,
  after_json  TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000)
);
CREATE TABLE mfa_secrets (
  user_id             TEXT        NOT NULL PRIMARY KEY,
  totp_secret_enc     TEXT        NOT NULL,
  totp_enabled        INTEGER     NOT NULL DEFAULT 0,
  backup_codes_json   TEXT,
  recovery_used_at    INTEGER,
  created_at          INTEGER     NOT NULL DEFAULT (unixepoch()),
  updated_at          INTEGER     NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE CASCADE
);
CREATE TABLE mfa_pending_sessions (
  session_id  TEXT     NOT NULL PRIMARY KEY,
  expires_at  INTEGER  NOT NULL,
  created_at  INTEGER  NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (session_id) REFERENCES session(id) ON DELETE CASCADE
);
CREATE TABLE affiliate_offers_catalog (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  offer_name TEXT NOT NULL,
  network TEXT NOT NULL CHECK (network IN ('clickbank','shareasale','amazon','impact','cj','manual')),
  url TEXT NOT NULL,
  commission_rate REAL,
  category TEXT,
  description TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE video_usage_monthly (
  user_id    TEXT NOT NULL,
  year_month TEXT NOT NULL,           -- "YYYY-MM", e.g. "2026-04"
  count      INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,           -- ISO 8601 timestamp

  PRIMARY KEY (user_id, year_month)
);
CREATE TABLE video_onboarding_events (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  org_id TEXT,
  payment_id TEXT NOT NULL UNIQUE,
  tier TEXT NOT NULL,
  video_id TEXT,
  delivery_status TEXT NOT NULL DEFAULT 'pending'
    CHECK(delivery_status IN ('pending','generating','delivered','email_sent','failed')),
  email_recipient TEXT,
  email_sent_at INTEGER,
  delivered_at INTEGER,
  error TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE cron_runs (
  id TEXT PRIMARY KEY,
  cron_name TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('success','failed','skipped')),
  run_at INTEGER NOT NULL,  -- epoch seconds
  duration_ms INTEGER,
  message TEXT,
  metadata TEXT  -- JSON
);
CREATE TABLE user_provider_credentials (
  id              TEXT    PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id         TEXT    NOT NULL,
  provider        TEXT    NOT NULL,
  encrypted_value TEXT    NOT NULL,
  display_hint    TEXT,
  created_at      INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
  updated_at      INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
  last_used_at    INTEGER,
  status          TEXT    NOT NULL DEFAULT 'active'
                  CHECK (status IN ('active', 'disabled', 'revoked')), key_version INTEGER DEFAULT 1,
  UNIQUE (user_id, provider)
);
CREATE TABLE user_purchases (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('subscription', 'one_time')),
  sku TEXT NOT NULL,
  payment_id TEXT NOT NULL UNIQUE,
  invoice_id TEXT,
  amount_cents INTEGER NOT NULL DEFAULT 0,
  credits_total INTEGER NOT NULL DEFAULT 0,
  credits_remaining INTEGER NOT NULL DEFAULT 0,
  expires_at INTEGER,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'paid', 'refunded', 'failed', 'underpaid')),
  created_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
  paid_at INTEGER,
  refunded_at INTEGER,
  updated_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE refund_requests (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  purchase_id TEXT NOT NULL,
  payment_id TEXT NOT NULL,
  amount_cents INTEGER NOT NULL,
  reason TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','refunded')),
  created_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),
  reviewed_at INTEGER,
  reviewed_by_user_id TEXT,
  admin_notes TEXT,
  refund_tx_hash TEXT,
  customer_wallet_address TEXT
);
CREATE TABLE pricing_overrides (
  sku TEXT PRIMARY KEY,
  price_cents INTEGER NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  metadata TEXT,  -- JSON: {"label_vi":"...", "label_en":"..."}
  updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),
  updated_by_user_id TEXT
);
CREATE TABLE admin_audit_log (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  actor_user_id TEXT NOT NULL,
  action_type TEXT NOT NULL,
  target_user_id TEXT,
  payload TEXT,  -- JSON string
  created_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))
);
CREATE TABLE engine_missions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  command TEXT NOT NULL,
  params TEXT,  -- JSON
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','succeeded','failed','cancelled')),
  result TEXT,  -- JSON
  error TEXT,
  credits_used INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),
  updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),
  completed_at INTEGER,
  webhook_url TEXT,
  webhook_fired_at INTEGER
, output_video_url TEXT, output_audio_url TEXT, video_job_id TEXT, checkpoint_json TEXT);
CREATE TABLE user_mcu_balance (
  user_id TEXT PRIMARY KEY,
  credits_remaining INTEGER NOT NULL DEFAULT 0,
  credits_total_purchased INTEGER NOT NULL DEFAULT 0,
  credits_total_used INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))
);
CREATE TABLE mcu_transactions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  delta INTEGER NOT NULL,
  reason TEXT NOT NULL,
  mission_id TEXT,
  metadata TEXT,
  created_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))
);
CREATE TABLE sop_runs (
  id TEXT PRIMARY KEY,
  installation_id TEXT NOT NULL,
  trigger_type TEXT NOT NULL CHECK (trigger_type IN ('cron','webhook','manual')),
  mission_ids TEXT NOT NULL DEFAULT '[]',  -- JSON array of engine_missions.id
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','partial')),
  result_summary TEXT,    -- JSON aggregate of step outputs
  error_message TEXT,
  requires_approval INTEGER NOT NULL DEFAULT 0,  -- 1 = paused, waiting for human gate
  started_at INTEGER,
  completed_at INTEGER,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (installation_id) REFERENCES user_sop_installations(id)
);
CREATE TABLE sop_templates (
  id TEXT PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  name_vi TEXT NOT NULL,
  name_en TEXT NOT NULL,
  description_vi TEXT NOT NULL,
  description_en TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('content','leads','email','analytics','proposals','crisis','sales','social')),
  agents_yaml TEXT NOT NULL,
  playbook_md TEXT NOT NULL,
  output_schema TEXT NOT NULL,
  config_schema TEXT,
  config_defaults TEXT,
  setup_time_minutes INTEGER NOT NULL DEFAULT 5,
  is_featured INTEGER NOT NULL DEFAULT 0,
  credits_per_run INTEGER NOT NULL DEFAULT 1,
  version INTEGER NOT NULL DEFAULT 1,
  is_official INTEGER NOT NULL DEFAULT 0,
  author_user_id TEXT,
  status TEXT NOT NULL DEFAULT 'published' CHECK (status IN ('draft','published','archived')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE supabase_migrations_applied (
  filename TEXT PRIMARY KEY,
  applied_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),
  applied_by_user_id TEXT NOT NULL,
  notes TEXT
);
CREATE TABLE audit_runs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  triggered_by_user_id TEXT NOT NULL,
  started_at INTEGER NOT NULL DEFAULT (unixepoch()),
  completed_at INTEGER,
  total_score INTEGER,
  total_checks INTEGER,
  passed INTEGER,
  warned INTEGER,
  failed INTEGER,
  results TEXT  -- JSON array of CheckResult[]
);
CREATE TABLE customer_handovers (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  customer_user_id TEXT NOT NULL,
  agency_name TEXT NOT NULL,
  agency_type TEXT,
  tier TEXT NOT NULL,
  starter_sops TEXT,  -- JSON array of SOP slugs pre-installed
  magic_link_token TEXT UNIQUE,
  magic_link_expires_at INTEGER,
  created_by_admin_id TEXT NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  welcome_email_sent_at INTEGER,
  customer_first_login_at INTEGER,
  customer_first_sop_install_at INTEGER,
  customer_first_run_at INTEGER,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','at_risk','churned'))
, source TEXT NOT NULL DEFAULT 'manual'
  CHECK (source IN ('manual', 'auto_payment', 'auto_signup')), trigger_payment_id TEXT);
CREATE TABLE promo_codes (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  code TEXT NOT NULL UNIQUE,
  description TEXT,
  discount_type TEXT NOT NULL CHECK (discount_type IN ('percent_off','fixed_off','free_trial','free_full')),
  discount_value INTEGER NOT NULL DEFAULT 0,
  applies_to_tier TEXT,
  applies_to_sku TEXT,
  max_uses INTEGER,
  used_count INTEGER NOT NULL DEFAULT 0,
  max_uses_per_user INTEGER NOT NULL DEFAULT 1,
  valid_from INTEGER NOT NULL DEFAULT (unixepoch()),
  valid_until INTEGER,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled','expired')),
  created_by_admin_id TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  metadata TEXT
);
CREATE TABLE promo_code_redemptions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  promo_code_id TEXT NOT NULL,
  promo_code TEXT NOT NULL,
  user_id TEXT NOT NULL,
  email TEXT,
  applied_to_tier TEXT,
  applied_to_sku TEXT,
  discount_applied_cents INTEGER NOT NULL DEFAULT 0,
  trial_days_granted INTEGER NOT NULL DEFAULT 0,
  redeemed_at INTEGER NOT NULL DEFAULT (unixepoch()),
  payment_id TEXT,
  handover_id TEXT,
  status TEXT NOT NULL DEFAULT 'redeemed' CHECK (status IN ('redeemed','reverted','reserved'))
);
CREATE TABLE org_branding (
  org_id              TEXT PRIMARY KEY,
  agency_name         TEXT,
  logo_url            TEXT,
  watermark_position  TEXT NOT NULL DEFAULT 'bottom-right',
  watermark_opacity   REAL NOT NULL DEFAULT 0.85,
  -- 'always' | 'master_plus' | 'never' — controls which tier sees the customer logo
  watermark_policy    TEXT NOT NULL DEFAULT 'master_plus',
  primary_color       TEXT,
  updated_at          INTEGER NOT NULL DEFAULT (unixepoch()),
  created_at          INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE pending_orders (
  order_id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  tier TEXT NOT NULL,
  period TEXT NOT NULL DEFAULT 'monthly',
  payment_method TEXT NOT NULL DEFAULT 'nowpayments',
  amount_usd_cents INTEGER NOT NULL,
  promo_code TEXT,
  customer_email TEXT,
  invoice_url TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  payment_id TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  completed_at TEXT
);
CREATE TABLE payos_events (
  event_id TEXT PRIMARY KEY,
  order_code TEXT NOT NULL,
  status TEXT NOT NULL,
  amount INTEGER NOT NULL,
  currency TEXT NOT NULL DEFAULT 'VND',
  payload TEXT NOT NULL,
  processed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE welcome_email_outbox (
  id TEXT PRIMARY KEY,
  payment_id TEXT NOT NULL UNIQUE,
  to_email TEXT NOT NULL,
  template TEXT NOT NULL DEFAULT 'welcome-magic-link',
  payload TEXT NOT NULL,   -- JSON: {ownerFullName, tier, magicLinkUrl, locale}
  status TEXT NOT NULL DEFAULT 'pending',  -- pending|sent|failed
  attempts INTEGER NOT NULL DEFAULT 0,
  next_retry_at INTEGER NOT NULL,
  last_error TEXT,
  created_at INTEGER NOT NULL,
  sent_at INTEGER
);
CREATE TABLE lifecycle_email_log (
  user_id TEXT NOT NULL,
  template TEXT NOT NULL,
  sent_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, template)
);
CREATE TABLE status_check (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts INTEGER NOT NULL,
  status TEXT NOT NULL,   -- 'ok' | 'degraded' | 'down'
  latency_ms INTEGER,
  error TEXT
);
CREATE TABLE status_day_rollup (
  date TEXT PRIMARY KEY,         -- YYYY-MM-DD
  total_checks INTEGER NOT NULL DEFAULT 0,
  ok_checks INTEGER NOT NULL DEFAULT 0,
  p99_ms INTEGER
);
CREATE TABLE status_incident (
  id TEXT PRIMARY KEY,
  started_at INTEGER NOT NULL,
  ended_at INTEGER,
  severity TEXT NOT NULL DEFAULT 'minor',  -- 'minor' | 'major' | 'critical'
  title TEXT NOT NULL,
  description TEXT,
  postmortem_url TEXT
);
CREATE TABLE raas_user_api_keys (
  id TEXT PRIMARY KEY,
  key_id TEXT NOT NULL UNIQUE,
  key_hash TEXT NOT NULL,
  owner_id TEXT NOT NULL,
  name TEXT NOT NULL,
  permissions TEXT NOT NULL DEFAULT '[]',
  rate_limit_per_min INTEGER NOT NULL DEFAULT 100,
  created_at INTEGER NOT NULL,
  expires_at INTEGER,
  revoked_at INTEGER,
  last_used_at INTEGER,
  FOREIGN KEY (owner_id) REFERENCES user(id) ON DELETE CASCADE
);
CREATE TABLE telegram_pending_pairing (
  chat_id TEXT PRIMARY KEY,
  code TEXT NOT NULL,
  requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL
);
CREATE TABLE webhook_endpoints (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  url TEXT NOT NULL,
  secret TEXT NOT NULL,
  events TEXT NOT NULL,  -- JSON array of event names
  active INTEGER NOT NULL DEFAULT 1,
  description TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_success_at TEXT,
  last_failure_at TEXT,
  failure_count INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE webhook_attempts (
  id TEXT PRIMARY KEY,
  endpoint_id TEXT NOT NULL,
  tenant_id TEXT NOT NULL,
  event TEXT NOT NULL,
  payload TEXT NOT NULL,  -- JSON
  attempt_num INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL,  -- 'pending' | 'success' | 'failed' | 'dead_letter'
  http_status INTEGER,
  response_body TEXT,
  error_message TEXT,
  next_retry_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at TEXT,
  FOREIGN KEY (endpoint_id) REFERENCES webhook_endpoints(id)
);
CREATE TABLE discovered_affiliates (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  network TEXT NOT NULL,
  external_id TEXT NOT NULL,
  product_name TEXT NOT NULL,
  product_url TEXT,
  commission_pct REAL,
  commission_flat_usd REAL,
  category TEXT,
  description TEXT,
  discovered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  raw_payload TEXT, score REAL, score_breakdown TEXT,
  UNIQUE(network, external_id)
);
CREATE TABLE url_to_revenue_jobs (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  url TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued', -- queued|scripting|rendering|publishing|completed|failed
  channels_json TEXT NOT NULL DEFAULT '[]',    -- JSON array of channel names
  locales_json TEXT NOT NULL DEFAULT '[]',     -- JSON array of locale codes
  variants_count INTEGER NOT NULL DEFAULT 3,
  tracking_id TEXT,                            -- FK to tracking_links.id (optional)
  product_title TEXT,
  product_description TEXT,
  product_image_url TEXT,
  product_price TEXT,
  variants_json TEXT NOT NULL DEFAULT '[]',    -- JSON array of URLToRevenueVariant
  error_message TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE tracking_links (
  id TEXT PRIMARY KEY,                         -- 8-char base62 ID
  tenant_id TEXT NOT NULL,
  destination_url TEXT NOT NULL,
  affiliate_id TEXT,                           -- FK to discovered_affiliates (optional)
  campaign_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE tracking_clicks (
  id TEXT PRIMARY KEY,
  link_id TEXT NOT NULL,
  ts TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ip_hash TEXT,              -- sha256(ip + tenant_secret) for privacy — raw IP NOT stored
  user_agent TEXT,
  referrer TEXT,
  country TEXT,              -- from CF-IPCountry header
  FOREIGN KEY (link_id) REFERENCES tracking_links(id)
);
CREATE TABLE tracking_conversions (
  id TEXT PRIMARY KEY,
  link_id TEXT NOT NULL,
  network TEXT,
  external_conversion_id TEXT,
  amount_usd REAL,
  ts TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  raw_payload TEXT,          -- JSON string of full postback payload
  FOREIGN KEY (link_id) REFERENCES tracking_links(id)
);
CREATE TABLE affiliate_network_credentials (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  network TEXT NOT NULL CHECK(network IN (
    'impact_radius','partnerstack','cj','shareasale','clickbank',
    'binance','bybit','bitget','coinbase'
  )),
  encrypted_credentials TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','invalid','rate_limited')),
  last_validated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(tenant_id, network)
);
CREATE TABLE tenant_settings (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  namespace TEXT NOT NULL,    -- 'branding' | 'scoring' | 'geo' | 'cron' | 'channels' | 'mcp' | etc
  value TEXT NOT NULL,        -- JSON blob
  schema_version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, crypto_jurisdiction TEXT DEFAULT 'US'
    CHECK (crypto_jurisdiction IN ('US', 'EU', 'VN', 'SG', 'JP')),
  UNIQUE(tenant_id, namespace)
);
CREATE TABLE user_api_keys (
  user_id       TEXT NOT NULL,
  provider      TEXT NOT NULL,
  encrypted_key BLOB NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now')), key_version INTEGER DEFAULT 1,
  PRIMARY KEY (user_id, provider)
);
CREATE TABLE IF NOT EXISTS "subscriptions" (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  polar_subscription_id TEXT,
  plan TEXT DEFAULT 'free',
  status TEXT DEFAULT 'active',
  current_period_start TEXT,
  current_period_end TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  trial_ends_at INTEGER,
  user_id TEXT,
  tier TEXT
, first_customer BOOLEAN DEFAULT 0, cash_payment INTEGER DEFAULT 0, cash_payment_note TEXT);
CREATE TABLE IF NOT EXISTS "org_members" (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  org_id TEXT NOT NULL REFERENCES organizations(id),
  user_id TEXT NOT NULL,
  role TEXT DEFAULT 'member',
  created_at TEXT DEFAULT (datetime('now')),
  UNIQUE(org_id, user_id)
);
CREATE TABLE IF NOT EXISTS "videos" (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  script_request_id TEXT,
  heygen_job_id TEXT,
  title TEXT,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'processing', 'completed', 'failed', 'failed_permanent')),
  video_url TEXT,
  thumbnail_url TEXT,
  duration_sec INTEGER,
  error TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at TEXT DEFAULT (datetime('now')),
  r2_key TEXT,
  r2_size_bytes INTEGER,
  purchase_id TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  last_attempt_at INTEGER,
  last_error TEXT,
  script TEXT,
  locale TEXT,
  provider TEXT NOT NULL DEFAULT 'heygen',
  access_revoked INTEGER NOT NULL DEFAULT 0,
  is_onboarding INTEGER NOT NULL DEFAULT 0
, completed_at INTEGER);
CREATE TABLE IF NOT EXISTS "publishing_channels" (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  provider TEXT NOT NULL CHECK(provider IN ('tiktok','youtube','instagram','pinterest','linkedin','zalo','facebook','twitter')),
  external_account_id TEXT NOT NULL,
  display_name TEXT,
  access_token TEXT NOT NULL,
  refresh_token TEXT,
  expires_at INTEGER,
  status TEXT NOT NULL CHECK(status IN ('active','disconnected','expired')) DEFAULT 'active',
  refreshing_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(tenant_id, provider, external_account_id)
);
CREATE TABLE IF NOT EXISTS "telegram_paired_chats" (
  chat_id  TEXT PRIMARY KEY,
  first_name TEXT,
  paired_at  TEXT NOT NULL DEFAULT (datetime('now')),
  paired_by  TEXT NOT NULL UNIQUE
);
CREATE TABLE publishing_jobs (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  video_id TEXT NOT NULL,
  channel_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('scheduled','uploading','processing','live','failed')),
  caption TEXT,
  hashtags_json TEXT,
  product_link TEXT,
  scheduled_at INTEGER NOT NULL,
  started_at INTEGER,
  finished_at INTEGER,
  retry_count INTEGER NOT NULL DEFAULT 0,
  error TEXT,
  created_at INTEGER NOT NULL,
  provider TEXT NOT NULL DEFAULT ''
);
CREATE TABLE publishing_results (
  id TEXT PRIMARY KEY,
  publishing_job_id TEXT NOT NULL,
  tenant_id TEXT NOT NULL,
  channel_post_id TEXT,
  post_url TEXT,
  metrics_json TEXT,
  published_at INTEGER NOT NULL,
  FOREIGN KEY (publishing_job_id) REFERENCES publishing_jobs(id)
);
CREATE TABLE channel_quotas (
  channel_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  day TEXT NOT NULL,
  daily_limit INTEGER NOT NULL,
  used_today INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (channel_id, day)
);
CREATE TABLE account_deletion_requests (
  user_id            TEXT PRIMARY KEY,
  tenant_id          TEXT NOT NULL,
  requested_at       INTEGER NOT NULL,
  scheduled_at       INTEGER NOT NULL,
  confirmation_token TEXT NOT NULL,
  confirmed_at       INTEGER,
  cancelled_at       INTEGER,
  created_at         INTEGER NOT NULL DEFAULT (unixepoch())
, confirmation_token_hash TEXT);
CREATE TABLE user_payout_settings (
  user_id TEXT PRIMARY KEY REFERENCES users(id),
  preferred_method TEXT CHECK (preferred_method IN ('usdt_trc20','usdt_erc20','bank_transfer')),
  payout_address TEXT,                     -- crypto wallet OR bank account; encrypt before WRITE (TODO M+1)
  payout_address_verified INTEGER DEFAULT 0,
  -- Stripe Connect Express columns (Phase 03)
  stripe_account_id TEXT,
  stripe_account_status TEXT,              -- 'pending' | 'enabled' | 'restricted' | 'rejected'
  stripe_payout_enabled INTEGER DEFAULT 0, -- 1 once charges_enabled+payouts_enabled
  stripe_onboarding_started_at TEXT,
  stripe_last_event_at TEXT,
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE stripe_connect_events (
  event_id TEXT PRIMARY KEY,            -- Stripe event.id (e.g. evt_1AbC2dE...)
  event_type TEXT NOT NULL,             -- e.g. 'account.updated'
  account_id TEXT,                      -- Stripe acct_... (nullable for non-account events)
  received_at TEXT NOT NULL DEFAULT (datetime('now')),
  processed INTEGER NOT NULL DEFAULT 0,
  error TEXT
);
CREATE TABLE commission_ledger (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  affiliate_id TEXT NOT NULL,
  conversion_event_id TEXT NOT NULL,
  offer_id TEXT NOT NULL,
  gross_cents INTEGER NOT NULL,
  commission_pct REAL NOT NULL,
  commission_cents INTEGER NOT NULL,
  withheld_cents INTEGER NOT NULL DEFAULT 0,
  parent_conversion_id TEXT,
  status TEXT CHECK(status IN ('pending','payable','paid','clawed_back','rejected','paying','clawback')) NOT NULL,
  payable_at INTEGER NOT NULL,
  paid_at INTEGER,
  payout_batch_id TEXT,
  clawback_reason TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(conversion_event_id)
);
CREATE TABLE payout_batches (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  affiliate_id TEXT NOT NULL,
  total_cents INTEGER NOT NULL,
  ledger_count INTEGER NOT NULL,
  status TEXT CHECK(status IN ('queued','sending','confirmed','failed')) NOT NULL,
  payment_method TEXT NOT NULL,
  external_payment_id TEXT,
  network TEXT DEFAULT 'TRC20',
  recipient_addr_encrypted TEXT NOT NULL,
  test_payment_confirmed INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL,
  finalized_at INTEGER
);
CREATE TABLE payout_methods (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  affiliate_id TEXT NOT NULL,
  method TEXT CHECK(method IN ('usdt_trc20','usdt_erc20','bank_account')) NOT NULL,
  recipient_addr_encrypted TEXT NOT NULL,
  display_label TEXT,
  is_default INTEGER DEFAULT 0,
  verified INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL,
  UNIQUE(tenant_id, affiliate_id, method, recipient_addr_encrypted)
);
CREATE TABLE telegram_pairing_tokens (
  token      TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  expires_at TEXT NOT NULL,
  used_at    TEXT
);
CREATE TABLE ab_experiments (
  id                    TEXT PRIMARY KEY,          -- uuid or short-id
  video_id              TEXT NOT NULL,             -- references video / offer
  tenant_id             TEXT NOT NULL,             -- tenant isolation

  -- Variant content
  variant_a_caption     TEXT NOT NULL,             -- Title / caption for variant A
  variant_b_caption     TEXT NOT NULL,             -- Title / caption for variant B
  variant_a_thumb_url   TEXT,                      -- Thumbnail URL for variant A (nullable = not generated yet)
  variant_b_thumb_url   TEXT,                      -- Thumbnail URL for variant B

  -- Counters (updated by tracking cron)
  impressions_a         INTEGER NOT NULL DEFAULT 0,
  impressions_b         INTEGER NOT NULL DEFAULT 0,
  conversions_a         INTEGER NOT NULL DEFAULT 0,
  conversions_b         INTEGER NOT NULL DEFAULT 0,

  -- Winner state: NULL = pending, 'a' = variant A won, 'b' = variant B won, 'no_winner' = no clear winner
  winner                TEXT CHECK (winner IN ('a', 'b', 'no_winner')),

  -- Lifecycle: 'active' | 'decided' | 'expired'
  status                TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'decided', 'expired')),

  created_at            TEXT NOT NULL,             -- ISO-8601
  decided_at            TEXT,                      -- ISO-8601; set when status changes to 'decided'

  -- Optional metadata
  offer_id              TEXT,                      -- affiliate offer ID (if applicable)
  bundle_id             TEXT                       -- bundle used for this experiment
);
CREATE TABLE help_videos (
  id TEXT PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  title_en TEXT NOT NULL,
  title_vi TEXT NOT NULL,
  description_en TEXT NOT NULL,
  description_vi TEXT NOT NULL,
  r2_key TEXT,
  duration_sec INTEGER NOT NULL DEFAULT 0,
  category TEXT NOT NULL DEFAULT 'general',
  order_index INTEGER NOT NULL DEFAULT 0,
  published INTEGER NOT NULL DEFAULT 0 CHECK (published IN (0, 1)),
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE affiliate_networks (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT UNIQUE NOT NULL,
  api_endpoint TEXT,
  postback_url TEXT,
  hmac_secret_key TEXT,
  active INTEGER DEFAULT 1,
  created_at INTEGER NOT NULL
);
CREATE TABLE affiliate_offers (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  network_id TEXT NOT NULL,
  external_id TEXT NOT NULL,
  title TEXT,
  description TEXT,
  image_url TEXT,
  product_url TEXT NOT NULL,
  commission_pct REAL,
  commission_fixed_usd REAL,
  niche TEXT,
  language TEXT,
  region TEXT,
  is_trending INTEGER DEFAULT 0,
  last_synced_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(network_id, external_id, tenant_id)
);
CREATE TABLE affiliate_links (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  offer_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  code TEXT UNIQUE NOT NULL,
  campaign_name TEXT,
  sub_id TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE click_events (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  link_id TEXT NOT NULL,
  offer_id TEXT NOT NULL,
  ip_hash TEXT,
  ua TEXT,
  referrer TEXT,
  country TEXT,
  clicked_at INTEGER NOT NULL
);
CREATE TABLE conversion_events (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  link_id TEXT NOT NULL,
  click_id TEXT,
  network_transaction_id TEXT NOT NULL,
  gross_amount_usd REAL NOT NULL,
  commission_usd REAL NOT NULL,
  status TEXT CHECK(status IN ('pending','approved','rejected','paid')),
  attributed_at INTEGER NOT NULL,
  UNIQUE(network_transaction_id)
);
CREATE TABLE IF NOT EXISTS "user_sop_installations" (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  template_id TEXT NOT NULL,
  customizations TEXT,
  schedule_cron TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  last_run_at INTEGER,
  next_run_at INTEGER,
  run_count INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  config_values TEXT,
  FOREIGN KEY (template_id) REFERENCES sop_templates(id)
);
CREATE TABLE openclaw_revoked_tokens (
  jti TEXT PRIMARY KEY,
  revoked_at INTEGER NOT NULL,  -- Unix epoch seconds
  reason TEXT
);
CREATE TABLE openclaw_mint_attempts (
  jti TEXT PRIMARY KEY,         -- links back to the minted token
  user_id TEXT NOT NULL,
  ip TEXT NOT NULL,
  created_at INTEGER NOT NULL   -- Unix epoch seconds
);
CREATE TABLE sop_executions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  org_id TEXT NOT NULL,
  sop_template_id TEXT NOT NULL,
  installation_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'running', 'paused', 'completed', 'failed')),
  input_json TEXT NOT NULL DEFAULT '{}',
  output_json TEXT,
  error_message TEXT,
  current_step INTEGER DEFAULT 0,
  total_steps INTEGER NOT NULL,
  step_results TEXT DEFAULT '[]',
  credits_used INTEGER DEFAULT 0,
  started_at INTEGER NOT NULL,
  completed_at INTEGER
);
CREATE TABLE sop_listings (
  id TEXT PRIMARY KEY,
  template_id TEXT NOT NULL UNIQUE,
  price_cents INTEGER NOT NULL,
  currency TEXT NOT NULL DEFAULT 'USD',
  preview_md TEXT,
  demo_video_url TEXT,
  tags TEXT,
  total_sales INTEGER DEFAULT 0,
  total_revenue_cents INTEGER DEFAULT 0,
  rating_avg REAL DEFAULT 0,
  rating_count INTEGER DEFAULT 0,
  status TEXT CHECK(status IN ('pending_review','published','rejected','suspended')) NOT NULL DEFAULT 'pending_review',
  rejection_reason TEXT,
  published_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE sop_licenses (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  template_id TEXT NOT NULL,
  listing_id TEXT NOT NULL,
  price_cents INTEGER NOT NULL,
  payment_id TEXT,
  payment_status TEXT CHECK(payment_status IN ('pending','paid','refunded')) NOT NULL DEFAULT 'pending',
  purchased_at INTEGER NOT NULL,
  refunded_at INTEGER,
  UNIQUE(user_id, template_id)
);
CREATE TABLE sop_execution_logs (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL,
  sop_template_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  step_index INTEGER NOT NULL,
  step_name TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('started','completed','failed','skipped')),
  input_hash TEXT,
  output_summary TEXT,
  duration_ms INTEGER,
  cost_cents INTEGER DEFAULT 0,
  error_message TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE sop_execution_metrics (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL UNIQUE,
  sop_template_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  total_duration_ms INTEGER NOT NULL,
  total_cost_cents INTEGER DEFAULT 0,
  steps_completed INTEGER NOT NULL DEFAULT 0,
  steps_failed INTEGER NOT NULL DEFAULT 0,
  quality_score REAL,
  user_rating INTEGER,
  feedback_text TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE creator_memory (
  id                   TEXT    PRIMARY KEY,
  user_id              TEXT    NOT NULL,
  -- 'episodic'   — specific execution results (e.g. "video X got 50K views with hook style Y")
  -- 'semantic'   — general knowledge about creator (e.g. "prefers casual tone, targets 18-35")
  -- 'preference' — explicit user preferences (e.g. "always use blue thumbnails")
  -- 'performance'— aggregated metrics (e.g. "avg CTR 4.2% on faceless videos")
  memory_type          TEXT    NOT NULL CHECK(memory_type IN ('episodic','semantic','preference','performance')),
  category             TEXT    NOT NULL,
  content_json         TEXT    NOT NULL,
  -- Higher = more relevant. Updated by decay/boost calls. Used for ranked retrieval.
  relevance_score      REAL    DEFAULT 1.0,
  source_execution_id  TEXT,
  -- Epoch ms. NULL = never expires.
  expires_at           INTEGER,
  created_at           INTEGER NOT NULL,
  updated_at           INTEGER NOT NULL
);
CREATE TABLE sop_graph_templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  graph_json TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  is_active INTEGER NOT NULL DEFAULT 1,
  category TEXT,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE sop_experiments (
  id TEXT PRIMARY KEY,
  sop_template_id TEXT NOT NULL,
  parameter_key TEXT NOT NULL,  -- which SOP parameter to vary (e.g. 'prompt_style', 'temperature')
  variants_json TEXT NOT NULL,  -- JSON array: [{key: 'control', value: ...}, {key: 'treatment', value: ...}]
  traffic_pct INTEGER NOT NULL DEFAULT 100,  -- percentage of executions enrolled (0-100)
  status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','concluded','archived')),
  winner_key TEXT,  -- set when concluded
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  concluded_at INTEGER
);
CREATE TABLE sop_experiment_assignments (
  id TEXT PRIMARY KEY,
  experiment_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  variant_key TEXT NOT NULL,
  execution_id TEXT,  -- links to sop_executions
  outcome_json TEXT,  -- arbitrary outcome data (quality_score, duration, user_rating, etc.)
  assigned_at INTEGER NOT NULL,
  outcome_at INTEGER
);
CREATE TABLE sop_step_confidence (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL,
  step_index INTEGER NOT NULL,
  score REAL NOT NULL,
  factors_json TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE escalation_requests (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL,
  step_index INTEGER NOT NULL,
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  resolved_by TEXT,
  resolved_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE sop_execution_outcomes (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL,
  sop_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  metric_type TEXT NOT NULL,
  metric_value REAL NOT NULL,
  source TEXT,
  recorded_at INTEGER NOT NULL
);
CREATE TABLE agent_execution_sessions (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL,
  supervisor_agent TEXT NOT NULL DEFAULT 'default',
  status TEXT NOT NULL DEFAULT 'pending',
  worker_count INTEGER NOT NULL DEFAULT 0,
  completed_count INTEGER NOT NULL DEFAULT 0,
  failed_count INTEGER NOT NULL DEFAULT 0,
  config_json TEXT,
  started_at INTEGER,
  completed_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE agent_task_assignments (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  agent_role TEXT NOT NULL,
  step_index INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  input_json TEXT,
  output_json TEXT,
  error_message TEXT,
  started_at INTEGER,
  completed_at INTEGER,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (session_id) REFERENCES agent_execution_sessions(id)
);
CREATE TABLE outcome_pricing_tiers (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  percentage REAL NOT NULL DEFAULT 15.0,
  min_revenue_cents INTEGER NOT NULL DEFAULT 0,
  max_revenue_cents INTEGER,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE outcome_billing_events (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  execution_id TEXT NOT NULL,
  outcome_id TEXT,
  gross_revenue_cents INTEGER NOT NULL,
  fee_cents INTEGER NOT NULL,
  fee_percentage REAL NOT NULL,
  pricing_tier_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  settled_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE api_keys (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  key_hash TEXT NOT NULL UNIQUE,
  key_prefix TEXT NOT NULL,
  name TEXT NOT NULL,
  permissions_json TEXT NOT NULL DEFAULT '["sop:execute","sop:read"]',
  rate_limit_rpm INTEGER NOT NULL DEFAULT 60,
  is_active INTEGER NOT NULL DEFAULT 1,
  last_used_at INTEGER,
  expires_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE api_request_log (
  id TEXT PRIMARY KEY,
  api_key_id TEXT NOT NULL,
  endpoint TEXT NOT NULL,
  method TEXT NOT NULL,
  status_code INTEGER NOT NULL,
  duration_ms INTEGER NOT NULL,
  request_body_size INTEGER,
  response_body_size INTEGER,
  error_message TEXT,
  ip_address TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE performance_feedback_cycles (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL,
  sop_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  published_at INTEGER NOT NULL,
  evaluate_at INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  metrics_json TEXT,
  evaluation_json TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE prompt_optimization_log (
  id TEXT PRIMARY KEY,
  cycle_id TEXT NOT NULL,
  sop_id TEXT NOT NULL,
  step_index INTEGER NOT NULL,
  original_prompt TEXT NOT NULL,
  suggested_prompt TEXT NOT NULL,
  improvement_score REAL,
  applied INTEGER NOT NULL DEFAULT 0,
  applied_at INTEGER,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (cycle_id) REFERENCES performance_feedback_cycles(id)
);
CREATE TABLE compliance_metadata (
  id TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL,
  content_id TEXT,
  user_id TEXT NOT NULL,
  compliance_type TEXT NOT NULL,
  metadata_json TEXT NOT NULL,
  platform TEXT,
  verified INTEGER NOT NULL DEFAULT 0,
  verified_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE media_jobs (
  id            TEXT    PRIMARY KEY,
  user_id       TEXT    NOT NULL,
  type          TEXT    NOT NULL CHECK(type IN ('image', 'video', 'audio')),
  model         TEXT    NOT NULL,
  prompt        TEXT,
  status        TEXT    NOT NULL DEFAULT 'pending',
  result_url    TEXT,
  thumbnail_url TEXT,
  error         TEXT,
  created_at    INTEGER NOT NULL DEFAULT (unixepoch()),
  completed_at  INTEGER
);
CREATE TABLE campaign_checkpoints (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  campaign_id TEXT NOT NULL REFERENCES campaigns(id),
  step TEXT NOT NULL,
  metadata TEXT DEFAULT '{}',
  completed_at TEXT DEFAULT (datetime('now')),
  UNIQUE(campaign_id, step)
);
CREATE TABLE repurpose_jobs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id TEXT NOT NULL,
  source_video_id TEXT NOT NULL,
  status TEXT DEFAULT 'analyzing',
  clip_manifest TEXT,
  total_clips INTEGER DEFAULT 0,
  completed_clips INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE repurpose_clips (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  job_id TEXT NOT NULL,
  clip_index INTEGER NOT NULL,
  start_ms INTEGER NOT NULL,
  end_ms INTEGER NOT NULL,
  score REAL,
  title TEXT,
  status TEXT DEFAULT 'pending',
  output_video_id TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (job_id) REFERENCES repurpose_jobs(id)
);
CREATE TABLE video_analytics (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id TEXT NOT NULL,
  video_id TEXT NOT NULL,
  platform TEXT NOT NULL,
  platform_video_id TEXT NOT NULL,
  date TEXT NOT NULL,
  views INTEGER DEFAULT 0,
  watch_time_sec INTEGER DEFAULT 0,
  completion_rate REAL DEFAULT 0.0,
  impressions INTEGER DEFAULT 0,
  clicks INTEGER DEFAULT 0,
  likes INTEGER DEFAULT 0,
  comments INTEGER DEFAULT 0,
  shares INTEGER DEFAULT 0,
  synced_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id),
  UNIQUE(video_id, platform, date)
);
CREATE TABLE thumbnail_variants (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  video_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  variant_index INTEGER NOT NULL,
  r2_key TEXT NOT NULL,
  strategy TEXT NOT NULL,
  impressions INTEGER DEFAULT 0,
  clicks INTEGER DEFAULT 0,
  is_selected INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE marketplace_templates (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  creator_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  template_config TEXT NOT NULL,
  preview_r2_key TEXT,
  price_cents INTEGER DEFAULT 0,
  downloads INTEGER DEFAULT 0,
  rating REAL DEFAULT 0.0,
  rating_count INTEGER DEFAULT 0,
  is_public INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (creator_id) REFERENCES users(id)
);
CREATE TABLE platform_credentials (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id TEXT NOT NULL,
  platform TEXT NOT NULL,
  access_token_encrypted TEXT NOT NULL,
  refresh_token_encrypted TEXT,
  token_expires_at TEXT,
  platform_user_id TEXT,
  platform_channel_name TEXT,
  scopes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')), key_version INTEGER DEFAULT 1,
  UNIQUE(user_id, platform)
);
CREATE TABLE video_publishes (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id TEXT NOT NULL,
  video_id TEXT NOT NULL,
  platform TEXT NOT NULL,
  platform_video_id TEXT,
  status TEXT DEFAULT 'pending',
  scheduled_at TEXT,
  published_at TEXT,
  error_message TEXT,
  metadata TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE sop_challenges (
  id TEXT PRIMARY KEY,
  title_en TEXT NOT NULL,
  title_vi TEXT NOT NULL,
  description_en TEXT,
  description_vi TEXT,
  goal_type TEXT CHECK(goal_type IN ('sop_runs','sop_sales','commission_earned','sops_created')) NOT NULL,
  goal_value INTEGER NOT NULL,
  reward_type TEXT CHECK(reward_type IN ('badge','credits','commission_boost')) NOT NULL,
  reward_value TEXT NOT NULL,
  starts_at INTEGER NOT NULL,
  ends_at INTEGER NOT NULL,
  status TEXT CHECK(status IN ('upcoming','active','ended')) NOT NULL DEFAULT 'upcoming',
  created_at INTEGER NOT NULL
);
CREATE TABLE user_challenge_progress (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  challenge_id TEXT NOT NULL,
  current_value INTEGER NOT NULL DEFAULT 0,
  completed_at INTEGER,
  reward_claimed INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(user_id, challenge_id)
);
CREATE TABLE beta_invites (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  email TEXT,
  commission_override_pct REAL NOT NULL DEFAULT 0.50,
  max_uses INTEGER NOT NULL DEFAULT 1,
  used_count INTEGER NOT NULL DEFAULT 0,
  expires_at INTEGER,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000)
);
CREATE TABLE batch_jobs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id TEXT NOT NULL,
  name TEXT NOT NULL,
  status TEXT DEFAULT 'pending',
  total_videos INTEGER NOT NULL,
  completed_videos INTEGER DEFAULT 0,
  failed_videos INTEGER DEFAULT 0,
  estimated_cost_cents INTEGER DEFAULT 0,
  actual_cost_cents INTEGER DEFAULT 0,
  input_r2_key TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  completed_at TEXT
, idempotency_key TEXT, fanout_dispatched_at TEXT);
CREATE TABLE batch_videos (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  batch_id TEXT NOT NULL,
  row_index INTEGER NOT NULL,
  status TEXT DEFAULT 'queued',
  mission_id TEXT,
  input_data TEXT NOT NULL,
  output_video_url TEXT,
  error_message TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  completed_at TEXT,
  FOREIGN KEY (batch_id) REFERENCES batch_jobs(id)
);
CREATE TABLE scheduled_campaigns (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL REFERENCES users(id),
  topic TEXT NOT NULL,
  template_script TEXT,
  interval_days INTEGER NOT NULL DEFAULT 7 CHECK (interval_days >= 1 AND interval_days <= 365),
  next_run_date TEXT NOT NULL,
  last_run_date TEXT,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE idempotency_keys (
  key TEXT PRIMARY KEY,
  refund_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'refunded',
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  expires_at INTEGER NOT NULL
);
CREATE TABLE referral_rewards (
  id TEXT PRIMARY KEY,
  referrer_id TEXT NOT NULL REFERENCES user(id),
  referred_user_id TEXT NOT NULL REFERENCES user(id),
  payment_id TEXT NOT NULL,
  reward_cents INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE(payment_id, referrer_id)
);
CREATE TABLE affiliate_conversions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  receipt TEXT NOT NULL,                   -- ClickBank txn ID
  click_id TEXT,                           -- FK to affiliate_clicks.click_id (NULL if unattributed)
  campaign_id TEXT REFERENCES campaigns(id),
  user_id TEXT REFERENCES users(id),
  offer_id TEXT,
  network TEXT NOT NULL DEFAULT 'clickbank',
  event_type TEXT NOT NULL CHECK (event_type IN ('SALE','REFUND','CHARGEBACK','TEST')),
  gross_amount REAL NOT NULL,              -- merchant-net commission ClickBank reports
  currency TEXT NOT NULL DEFAULT 'USD',
  commission_user REAL NOT NULL,           -- 70% of gross_amount
  commission_sophia REAL NOT NULL,         -- 30% of gross_amount
  payout_status TEXT NOT NULL DEFAULT 'pending_clearance'
    CHECK (payout_status IN ('pending_clearance','available','paid','reversed','unattributed')),
  available_at INTEGER,                    -- Unix seconds: ts + 60 days for SALE
  paid_at INTEGER,                         -- Set when admin marks paid (M5)
  payout_id TEXT,                          -- Reference to payout batch (M5)
  raw_payload TEXT,                        -- Full INS payload for audit
  created_at TEXT DEFAULT (datetime('now')),
  UNIQUE(receipt, event_type)              -- idempotency
);
CREATE TABLE org_quota_overrides (
  org_id TEXT NOT NULL PRIMARY KEY,
  missions INTEGER NOT NULL,
  credentials INTEGER NOT NULL,
  members INTEGER NOT NULL,
  webhooks INTEGER NOT NULL,
  api_keys INTEGER NOT NULL,
  set_by TEXT NOT NULL,
  set_at INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE CASCADE,
  FOREIGN KEY (set_by) REFERENCES users(id)
);
CREATE TABLE key_versions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  key_type TEXT NOT NULL, -- 'master' | 'credential' | 'platform'
  version INTEGER NOT NULL, -- monotonically increasing per key_type
  encrypted_key TEXT NOT NULL, -- the new master key material, encrypted at rest
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  rotated_at TEXT, -- NULL until rotation supersedes it
  rotated_by TEXT, -- admin user id who triggered rotation
  is_active INTEGER NOT NULL DEFAULT 1, -- 1 = current, 0 = retired
  UNIQUE(key_type, version)
);
