CREATE TRIGGER trg_campaigns_set_org_id
AFTER INSERT ON campaigns
WHEN NEW.org_id IS NULL
BEGIN
  UPDATE campaigns
  SET org_id = (
    SELECT om.org_id
    FROM org_members om
    WHERE om.user_id = NEW.user_id
    ORDER BY om.created_at ASC
    LIMIT 1
  )
  WHERE id = NEW.id;
END;
CREATE TRIGGER trg_campaigns_reject_null_org_update
BEFORE UPDATE OF org_id ON campaigns
WHEN NEW.org_id IS NULL
BEGIN
  SELECT RAISE(ABORT, 'campaigns.org_id cannot be NULL');
END;
CREATE TRIGGER trg_campaigns_assert_org_after_insert
AFTER INSERT ON campaigns
WHEN (SELECT org_id FROM campaigns WHERE id = NEW.id) IS NULL
BEGIN
  SELECT RAISE(ABORT, 'campaigns.org_id failed to auto-populate (user has no org_members row)');
END;
CREATE TRIGGER trg_admin_audit_log_immutable
BEFORE UPDATE ON admin_audit_log
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'admin_audit_log is immutable - UPDATE prohibited (CC6.6)');
END;
CREATE TRIGGER trg_admin_audit_log_no_delete
BEFORE DELETE ON admin_audit_log
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'admin_audit_log is immutable - DELETE prohibited (CC6.6)');
END;
CREATE VIEW v_audit_log_health AS
SELECT
  'admin_audit_log'         AS table_name,
  COUNT(*)                  AS total_entries,
  MIN(created_at)           AS oldest_entry,
  MAX(created_at)           AS newest_entry,
  COUNT(DISTINCT actor_user_id) AS distinct_actors
FROM admin_audit_log;
